#[test]
fn back_target_applied_report_existing_mismatch_is_bounded_and_zero_write() {
    let mut app = App::new();
    app.add_plugins(BevyUiRouterPlugin::default());
    let router =
        install_atomic_router_at_pattern(&mut app, "back-target-applied-existing-mismatch", "/:id");
    app.update();
    for location in ["/a", "/b"] {
        let request = app
            .world_mut()
            .resource_mut::<RouterNavigation>()
            .push(router, RouteLocation::new(location))
            .unwrap();
        run_updates_until_succeeded(&mut app, request);
    }

    let back = app
        .world_mut()
        .resource_mut::<RouterNavigation>()
        .back(router)
        .expect("the real active route has one predecessor");
    collect_navigation_system(app.world_mut());
    drive_navigation_system(app.world_mut());
    publish_snapshots_system(app.world_mut());
    let placeholder_task =
        foreign_fallback_task("back-target-applied-existing-mismatch-placeholder");

    let (pending, task) = app.world_mut().resource_scope(
        |_world, mut navigation: bevy_ecs::change_detection::Mut<RouterNavigation>| {
            let entry = navigation
                .entries
                .iter_mut()
                .find(|entry| entry.handle == router)
                .expect("the exact router retains its entry");
            let Some(PendingBackTargetExecution::Driving(driving)) =
                entry.pending_back_target_execution.take()
            else {
                panic!("the real root Back must reach its Driving owner")
            };
            let _detached_missing_stage_owner = driving;
            let mut pending = entry
                .pending_commit
                .take()
                .expect("the real root target retains one pending commit");
            let task = pending
                .final_task
                .take()
                .expect("the real root target retains its final applied task");
            assert!(entry.engine.is_current_root_back_frame_task(&task));

            assert!(matches!(
                store_back_target_applied_staging_mismatch(
                    entry,
                    None,
                    BackTargetDriverStagingMismatchObservation::Missing,
                    PendingCommit::new(),
                    placeholder_task,
                    BackTargetAppliedReport::LegacyLeaf,
                ),
                RouteBackTargetAppliedOutcome::Handled
            ));
            (pending, task)
        },
    );

    let core_before = app.world().resource::<RouterNavigation>().entries[0]
        .engine
        .snapshot();
    let request_before = {
        let navigation = app.world().resource::<RouterNavigation>();
        let request = navigation.entries[0]
            .engine
            .request(back)
            .expect("the staged Back remains retained");
        (
            request.requested().cloned(),
            request.status().clone(),
            request.trace().to_vec(),
        )
    };
    let world_before = authority_world_fingerprint(app.world());
    let registry_before = app
        .world()
        .resource::<RouteEntityRegistry>()
        .records()
        .to_vec();
    let seal_before = app
        .world()
        .resource::<RouteEntityRegistry>()
        .latest_issued_seal();
    let public_router_before = app
        .world()
        .resource::<RouterSnapshots>()
        .get(router)
        .expect("the exact router has a public snapshot")
        .clone();
    let public_request_before = match app
        .world()
        .resource::<RouterSnapshots>()
        .request(router, back)
    {
        crate::snapshots::RequestLookup::Found(snapshot) => snapshot.clone(),
        _ => panic!("the staged Back has a public request snapshot"),
    };

    app.world_mut().resource_scope(
        |_world, mut navigation: bevy_ecs::change_detection::Mut<RouterNavigation>| {
            let entry = navigation
                .entries
                .iter_mut()
                .find(|entry| entry.handle == router)
                .expect("the exact router retains its entry");
            assert!(matches!(
                entry.pending_back_target_execution.as_ref(),
                Some(PendingBackTargetExecution::AppliedReportStagingMismatch(_))
            ));
            assert!(entry.engine.is_current_root_back_frame_task(&task));
            assert!(matches!(
                route_back_target_applied_report(
                    entry,
                    pending,
                    task,
                    BackTargetAppliedReport::LegacyLeaf,
                ),
                RouteBackTargetAppliedOutcome::Handled
            ));
        },
    );

    let navigation = app.world().resource::<RouterNavigation>();
    let entry = navigation
        .entries
        .iter()
        .find(|entry| entry.handle == router)
        .expect("the exact router retains its entry");
    assert_eq!(entry.engine.snapshot(), core_before);
    let request_after = entry
        .engine
        .request(back)
        .expect("the safe-stopped Back remains retained");
    assert_eq!(
        (
            request_after.requested().cloned(),
            request_after.status().clone(),
            request_after.trace().to_vec(),
        ),
        request_before
    );
    assert_eq!(authority_world_fingerprint(app.world()), world_before);
    assert_eq!(
        app.world().resource::<RouteEntityRegistry>().records(),
        registry_before
    );
    assert_eq!(
        app.world()
            .resource::<RouteEntityRegistry>()
            .latest_issued_seal(),
        seal_before
    );
    let snapshots = app.world().resource::<RouterSnapshots>();
    assert_eq!(
        snapshots
            .get(router)
            .expect("the public router snapshot remains retained"),
        &public_router_before
    );
    assert!(matches!(
        snapshots.request(router, back),
        crate::snapshots::RequestLookup::Found(snapshot)
            if snapshot == &public_request_before
    ));

    let Some(PendingBackTargetExecution::AppliedReportStagingConflict(conflict)) =
        entry.pending_back_target_execution.as_ref()
    else {
        panic!("re-entry must retain one flat typed applied staging conflict")
    };
    let existing = &conflict.existing;
    let _existing_whole_pending = (
        &existing.pending.ticket,
        &existing.pending.final_task,
        &existing.pending.branch,
    );
    assert!(!entry.engine.is_current_root_back_frame_task(&existing.task));
    assert!(matches!(
        existing.report,
        BackTargetAppliedReport::LegacyLeaf
    ));
    assert!(matches!(
        existing.evidence.observed,
        BackTargetDriverStagingMismatchObservation::Missing
    ));
    assert!(existing.previous.is_none());
    let incoming = &conflict.incoming;
    let _blocked_whole_pending = (
        &incoming.pending.ticket,
        &incoming.pending.final_task,
        &incoming.pending.branch,
    );
    assert!(entry.engine.is_current_root_back_frame_task(&incoming.task));
    assert!(matches!(
        incoming.report,
        BackTargetAppliedReport::LegacyLeaf
    ));
    assert!(matches!(
        conflict.evidence.observed,
        BackTargetDriverStagingMismatchObservation::ExistingAppliedMismatch
    ));
    assert!(
        conflict.evidence.pairing.is_none(),
        "staging conflict evidence must not fabricate a receiver pairing mismatch"
    );
}

fn stage_real_back_target_applied_commit(
    app: &mut App,
    router: RouterHandle,
) -> bevy_ui_router_core::prelude::NavigationRequestId {
    let back = app
        .world_mut()
        .resource_mut::<RouterNavigation>()
        .back(router)
        .expect("the real active route has one predecessor");
    collect_navigation_system(app.world_mut());
    drive_navigation_system(app.world_mut());
    app.world_mut().resource_scope(
        |_world, mut navigation: bevy_ecs::change_detection::Mut<RouterNavigation>| {
            let entry = navigation
                .entries
                .iter_mut()
                .find(|entry| entry.handle == router)
                .unwrap();
            let mut pending = entry
                .pending_commit
                .take()
                .expect("the real root target driver retains one pending commit");
            let task = pending
                .final_task
                .take()
                .expect("the applied root target retains its final report task");
            assert!(matches!(
                route_back_target_applied_report(
                    entry,
                    pending,
                    task,
                    BackTargetAppliedReport::LegacyLeaf,
                ),
                RouteBackTargetAppliedOutcome::Handled
            ));
            assert!(matches!(
                entry.pending_back_target_execution.as_ref(),
                Some(PendingBackTargetExecution::ResumeBlocked(
                    PendingBackTargetResumeBlocked::AppliedCommitPending(_)
                ))
            ));
        },
    );
    back
}

#[derive(Clone, Debug, Eq, PartialEq)]
struct ClassifierPermanentSourceProjection {
    history: HistoryExecutionBindingView,
    preserved: Vec<ExactRegistryClaim>,
    entering: Vec<ExactRegistryClaim>,
    leaving: Vec<ExactRegistryClaim>,
    allowed_write_targets: Vec<Entity>,
    evidence: (
        LifecyclePreflightSource,
        LifecyclePreflightExpectation,
        LifecyclePreflightObserved,
    ),
}

impl ClassifierPermanentSourceProjection {
    fn capture(owner: &PreparationPermanentOwner<TargetPreparationOwner>) -> Self {
        Self::capture_parts(&owner.owner.splice, &owner.owner.history, &owner.evidence)
    }

    fn capture_parts(
        splice: &SealedReconciliationSplice,
        history: &HistoryExecutionBindingView,
        permanent: &PreparationPermanentEvidence,
    ) -> Self {
        let mut allowed_write_targets = splice
            .leaving()
            .claims()
            .chain(splice.entering().claims())
            .map(ExactRegistryClaim::entity)
            .collect::<Vec<_>>();
        allowed_write_targets.sort_by_key(|entity| entity.to_bits());
        allowed_write_targets.dedup();
        let evidence = match permanent {
            PreparationPermanentEvidence::PhysicalPreparationContradiction(evidence) => evidence,
            #[cfg(feature = "bsn")]
            PreparationPermanentEvidence::NativeCleanup(_) => {
                panic!("expected physical preparation contradiction")
            }
        };
        Self {
            history: history.clone(),
            preserved: splice.preserved().claims().cloned().collect(),
            entering: splice.entering().claims().cloned().collect(),
            leaving: splice.leaving().claims().cloned().collect(),
            allowed_write_targets,
            evidence: (
                evidence.source(),
                evidence.expectation(),
                evidence.observed(),
            ),
        }
    }
}

struct StagedClassifierPermanent {
    request: NavigationRequestId,
    owner: PreparationPermanentOwner<TargetPreparationOwner>,
    host: Entity,
    top_slot: Entity,
    protected: [Entity; 2],
    drifted_mount_children: Vec<Entity>,
}

#[derive(Clone, Eq, PartialEq)]
struct ClassifierPermanentPendingCommitProjection {
    ticket: Option<ViewReportIdentity>,
    final_task: Option<ViewReportIdentity>,
    frames: Vec<RouteFrameVersion>,
    claims: Vec<ExactRegistryClaim>,
}

#[derive(Clone, Eq, PartialEq)]
struct ClassifierPermanentEntryLocalProjection {
    pending_commit: Option<ClassifierPermanentPendingCommitProjection>,
    active_frames: Option<Vec<RouteFrameVersion>>,
    back_capacity_reservations: Vec<(
        NavigationRequestId,
        NavigationRequestId,
        (u64, usize, u64, u64),
    )>,
    pending_back_target_execution_occupied: bool,
    cleanup_ledger_occupied: bool,
    authority_protocol_residual_occupied: bool,
    pending_back_no_target_completion_occupied: bool,
    pending_back_no_target_preparation_occupied: bool,
    pending_back_no_target_authority_cleanup_occupied: bool,
    pending_back_target_permanent_cleanup_occupied: bool,
}

impl ClassifierPermanentEntryLocalProjection {
    fn capture(entry: &RouterEntry) -> Self {
        Self {
            pending_commit: entry.pending_commit.as_ref().map(|pending| {
                ClassifierPermanentPendingCommitProjection {
                    ticket: pending.ticket.as_ref().map(CommitTicket::report_identity),
                    final_task: pending
                        .final_task
                        .as_ref()
                        .map(RootFrameTask::report_identity),
                    frames: pending
                        .branch
                        .frames()
                        .iter()
                        .map(|frame| frame.frame().clone())
                        .collect(),
                    claims: pending.branch.as_realized().claims().cloned().collect(),
                }
            }),
            active_frames: entry.active.as_ref().map(|active| {
                active
                    .frames()
                    .iter()
                    .map(|frame| frame.frame().clone())
                    .collect()
            }),
            back_capacity_reservations: entry
                .back_capacity_reservations
                .iter()
                .map(|(request, reservation)| {
                    (
                        *request,
                        reservation.request(),
                        reservation.capacity_identity_for_test(),
                    )
                })
                .collect(),
            pending_back_target_execution_occupied: entry.pending_back_target_execution.is_some(),
            cleanup_ledger_occupied: entry.cleanup_ledger.is_some(),
            authority_protocol_residual_occupied: entry.authority_protocol_residual.is_some(),
            pending_back_no_target_completion_occupied: entry
                .pending_back_no_target_completion
                .is_some(),
            pending_back_no_target_preparation_occupied: entry
                .pending_back_no_target_preparation
                .is_some(),
            pending_back_no_target_authority_cleanup_occupied: entry
                .pending_back_no_target_authority_cleanup
                .is_some(),
            pending_back_target_permanent_cleanup_occupied: entry
                .pending_back_target_permanent_cleanup
                .is_some(),
        }
    }
}

fn move_hierarchy_child_to_end(world: &mut World, child: Entity) {
    let parent = world
        .get::<ChildOf>(child)
        .map(ChildOf::parent)
        .expect("the real mounted shell retains its physical parent");
    let relationship = world
        .entity_mut(child)
        .take::<ChildOf>()
        .expect("the real mounted shell retains its ChildOf owner");
    world.entity_mut(child).insert(relationship);
    world.flush();
    assert_eq!(
        world.get::<ChildOf>(child).map(ChildOf::parent),
        Some(parent),
        "the source-fact drift changes only real sibling order"
    );
}

fn install_classifier_permanent_fixture(
    app: &mut App,
    name: &'static str,
) -> (RouterHandle, [Entity; 2]) {
    let router = install_atomic_router_at_pattern(app, name, "/:id");
    app.update();
    let host = app
        .world()
        .resource::<RouterNavigation>()
        .entries
        .iter()
        .find(|entry| entry.handle == router)
        .expect("the admitted router retains its exact entry")
        .host
        .as_ref()
        .expect("the admitted router retains its app-owned host")
        .host;
    let protected_root = app.world_mut().spawn(ChildOf(host)).id();
    let protected_leaf = app.world_mut().spawn(ChildOf(protected_root)).id();
    for location in ["/a", "/b"] {
        let request = app
            .world_mut()
            .resource_mut::<RouterNavigation>()
            .push(router, RouteLocation::new(location))
            .expect("the real fixture accepts its forward request");
        run_updates_until_succeeded(app, request);
    }
    (router, [protected_root, protected_leaf])
}

fn stage_real_back_target_classifier_permanent(
    app: &mut App,
    router: RouterHandle,
    protected: [Entity; 2],
    restore_exact_physical_facts: bool,
) -> StagedClassifierPermanent {
    let request = stage_real_back_target_applied_commit(app, router);
    let (host, top_slot, leaving_shell, entering_shell, exact_mount_children) = {
        let navigation = app.world().resource::<RouterNavigation>();
        let entry = navigation
            .entries
            .iter()
            .find(|entry| entry.handle == router)
            .expect("the real classifier fixture retains its entry");
        let host = entry
            .host
            .as_ref()
            .expect("the real classifier fixture retains its HostBinding");
        let leaving_shell = entry
            .active
            .as_ref()
            .and_then(RealizedBranch::first_frame)
            .expect("the real classifier fixture retains one active leaving frame")
            .shell();
        let Some(PendingBackTargetExecution::ResumeBlocked(
            PendingBackTargetResumeBlocked::AppliedCommitPending(applied),
        )) = entry.pending_back_target_execution.as_ref()
        else {
            panic!("the real applied commit must retain its whole pending owner")
        };
        let entering_shell = applied
            .pending
            .branch
            .last_frame()
            .expect("the real applied commit retains one entering frame")
            .shell();
        let exact_mount_children = app
            .world()
            .get::<Children>(host.top_slot)
            .expect("the exact top slot contains leaving and entering shells")
            .iter()
            .copied()
            .collect::<Vec<_>>();
        (
            host.host,
            host.top_slot,
            leaving_shell,
            entering_shell,
            exact_mount_children,
        )
    };
    assert_eq!(
        exact_mount_children,
        vec![leaving_shell, entering_shell],
        "the real splice starts with the canonical replacement ordering"
    );

    move_hierarchy_child_to_end(app.world_mut(), leaving_shell);
    let drifted_mount_children = app
        .world()
        .get::<Children>(top_slot)
        .expect("the drifted top slot still retains both exact shells")
        .iter()
        .copied()
        .collect::<Vec<_>>();
    assert_eq!(
        drifted_mount_children,
        vec![entering_shell, leaving_shell],
        "the real classifier predicate input is independently drifted"
    );

    let owner = app.world_mut().resource_scope(
            |world, mut navigation: bevy_ecs::change_detection::Mut<RouterNavigation>| {
                let entry = navigation
                    .entries
                    .iter_mut()
                    .find(|entry| entry.handle == router)
                    .expect("the real classifier fixture retains its entry");
                assert!(
                    drive_back_target_applied_commit(world, entry),
                    "the real applied commit must reach the production classifier"
                );
                let Some(PendingBackTargetExecution::Classifying(
                    PendingBackTargetClassification::Permanent(owner),
                )) = entry.pending_back_target_execution.take()
                else {
                    panic!(
                        "the real mount-order contradiction must produce the whole classifier permanent owner"
                    )
                };
                owner
            },
        );
    assert_eq!(
        ClassifierPermanentSourceProjection::capture(&owner).evidence,
        (
            LifecyclePreflightSource::TargetPartition,
            LifecyclePreflightExpectation::ExactRelationshipClosure,
            LifecyclePreflightObserved::Contradictory,
        ),
        "the source must come from the real classifier physical-manifest predicate"
    );

    if restore_exact_physical_facts {
        move_hierarchy_child_to_end(app.world_mut(), entering_shell);
        assert_eq!(
            app.world()
                .get::<Children>(top_slot)
                .expect("the restored top slot retains both exact shells")
                .iter()
                .copied()
                .collect::<Vec<_>>(),
            exact_mount_children,
            "the exact adapter fixture restores the real World fact before refreeze"
        );
    }

    StagedClassifierPermanent {
        request,
        owner,
        host,
        top_slot,
        protected,
        drifted_mount_children,
    }
}

#[test]
fn precommit_authority_takeover_preserves_history_until_settlement() {
    let mut app = App::new();
    app.add_plugins(BevyUiRouterPlugin::default());
    install_provisional_detach_reentry(&mut app);
    let (router, _) =
        install_classifier_permanent_fixture(&mut app, "back-precommit-authority-takeover");
    let request = stage_real_back_target_applied_commit(&mut app, router);
    let (drifted_current, history_before, active_before) = {
        let entry = app
            .world()
            .resource::<RouterNavigation>()
            .entries
            .iter()
            .find(|entry| entry.handle == router)
            .expect("the real Back target retains its exact entry");
        (
            entry
                .active
                .as_ref()
                .and_then(RealizedBranch::first_frame)
                .and_then(|frame| frame.interactive_entities().first().copied())
                .expect("the current Back source has one real interactive output"),
            entry.engine.history().clone(),
            entry.engine.active().clone(),
        )
    };
    app.world_mut()
        .entity_mut(drifted_current)
        .remove::<Pickable>();
    app.world_mut().flush();

    commit_presentation_system(app.world_mut());

    {
        let entry = app
            .world()
            .resource::<RouterNavigation>()
            .entries
            .iter()
            .find(|entry| entry.handle == router)
            .expect("the authority takeover retains the RouterEntry");
        assert_eq!(entry.engine.history(), &history_before);
        assert_eq!(entry.engine.active(), &active_before);
        assert_eq!(
            entry.engine.snapshot().availability(),
            &RouterAvailability::RecoveringAuthority
        );
        assert!(
            entry.pending_back_target_permanent_cleanup.is_some(),
            "the classified current-authority loss must install the scoped settlement owner"
        );
        assert!(entry.cleanup_ledger.is_none());
        assert!(entry.authority_protocol_residual.is_none());
        assert!(
            entry
                .engine
                .request(request)
                .expect("the Back request remains retained during settlement")
                .trace()
                .iter()
                .all(|event| { event.kind() != NavigationTraceEventKind::HistoryIntentRejected })
        );
    }

    let mut saw_scoped_settlement = false;
    for _ in 0..32 {
        settle_cleanup_system(app.world_mut());
        let entry = app
            .world()
            .resource::<RouterNavigation>()
            .entries
            .iter()
            .find(|entry| entry.handle == router)
            .expect("the settlement retains its RouterEntry shell");
        let record = entry
            .engine
            .request(request)
            .expect("the settlement request remains retained");
        saw_scoped_settlement |= record.trace().iter().any(|event| {
            event.kind() == NavigationTraceEventKind::CleanupSettled
                && event.cleanup_disposition().is_none()
        });
        assert_eq!(entry.engine.history(), &history_before);
        if entry.pending_back_target_permanent_cleanup.is_some() {
            assert_eq!(
                entry.engine.active(),
                &active_before,
                "active presentation cannot clear before scoped settlement completion"
            );
        }
        if entry.pending_back_target_permanent_cleanup.is_none()
            && matches!(record.status(), RequestStatus::Failed(_))
        {
            break;
        }
    }

    let entry = app
        .world()
        .resource::<RouterNavigation>()
        .entries
        .iter()
        .find(|entry| entry.handle == router)
        .expect("terminal settlement retains the RouterEntry shell");
    let record = entry
        .engine
        .request(request)
        .expect("terminal authority failure remains retained");
    assert!(saw_scoped_settlement);
    assert!(matches!(
        record.status(),
        RequestStatus::Failed(failure)
            if matches!(
                failure.kind(),
                NavigationFailureKind::HostLost | NavigationFailureKind::AuthorityLost
            )
    ));
    assert!(
        record
            .trace()
            .iter()
            .all(|event| { event.kind() != NavigationTraceEventKind::HistoryIntentRejected })
    );
    assert_eq!(entry.engine.history(), &history_before);
    assert_eq!(entry.engine.active().kind(), ActivePresentationKind::None);
    assert!(entry.pending_back_target_execution.is_none());
    assert!(entry.pending_back_target_permanent_cleanup.is_none());
    assert!(entry.cleanup_ledger.is_none());
    let terminal_owners = entry.engine.testing_back_target_permanent_begin_state();
    assert_eq!(terminal_owners.current_owner_count(), 0);
    assert_eq!(terminal_owners.action_owner_count(), 0);
    assert_eq!(terminal_owners.current_history_slot_count(), 0);
    assert_eq!(terminal_owners.cleanup_history_owner_count(), 0);
    assert_eq!(terminal_owners.cleanup_settlement_owner_count(), 0);
    assert_eq!(terminal_owners.conflicting_owner_count(), 0);
}

#[test]
fn back_target_missing_pickable_repair_refreezes_after_each_hook_write() {
    #[derive(Resource)]
    struct MissingPickableRepairHookDrift {
        targets: [Entity; 2],
        protected_root: Entity,
        first_insert: Option<Entity>,
        later_insertions: usize,
    }

    let mut app = App::new();
    app.world_mut()
        .register_component_hooks::<Pickable>()
        .on_insert(|mut world, HookContext { entity, .. }| {
            let Some(mut drift) = world.get_resource_mut::<MissingPickableRepairHookDrift>() else {
                return;
            };
            if !drift.targets.contains(&entity) {
                return;
            }
            if let Some(first) = drift.first_insert {
                if first != entity {
                    drift.later_insertions += 1;
                }
                return;
            }
            drift.first_insert = Some(entity);
            let protected_root = drift.protected_root;
            drop(drift);
            world
                .commands()
                .entity(protected_root)
                .insert(ChildOf(entity));
        });
    app.add_plugins(BevyUiRouterPlugin::default());
    let (router, [protected_root, _]) = install_classifier_permanent_fixture(
        &mut app,
        "back-target-missing-pickable-per-write-refreeze",
    );
    let request = stage_real_back_target_applied_commit(&mut app, router);
    let (host, repair_targets, history_before, active_before) = {
        let entry = app
            .world()
            .resource::<RouterNavigation>()
            .entries
            .iter()
            .find(|entry| entry.handle == router)
            .expect("the real Back target retains its exact RouterEntry");
        let current = entry
            .active
            .as_ref()
            .and_then(RealizedBranch::first_frame)
            .and_then(|frame| frame.interactive_entities().first().copied())
            .expect("the current branch retains one real Pickable target");
        let Some(PendingBackTargetExecution::ResumeBlocked(
            PendingBackTargetResumeBlocked::AppliedCommitPending(applied),
        )) = entry.pending_back_target_execution.as_ref()
        else {
            panic!("the real Back target must wait at its applied Commit owner")
        };
        let entering = applied
            .pending
            .branch
            .last_frame()
            .and_then(|frame| frame.interactive_entities().first().copied())
            .expect("the entering branch retains a second real Pickable target");
        assert_ne!(current, entering);
        (
            entry
                .host
                .as_ref()
                .expect("the admitted router retains its app-owned host")
                .host,
            [current, entering],
            entry.engine.history().clone(),
            entry.engine.active().clone(),
        )
    };
    assert_eq!(
        app.world()
            .get::<ChildOf>(protected_root)
            .map(ChildOf::parent),
        Some(host)
    );
    for target in repair_targets {
        assert!(app.world().get::<Pickable>(target).is_some());
        app.world_mut().entity_mut(target).remove::<Pickable>();
    }
    app.world_mut().flush();
    let pickable_component = app
        .world()
        .components()
        .component_id::<Pickable>()
        .expect("the real fixture registers Pickable");
    for target in repair_targets {
        assert!(app.world().get::<Pickable>(target).is_none());
        assert!(
            app.world()
                .resource::<RouteEntityRegistry>()
                .record(target)
                .is_some_and(|record| record
                    .manifest()
                    .component_ids()
                    .contains(&pickable_component)),
            "both repairs must be real exact target-manifest contradictions"
        );
    }

    commit_presentation_system(app.world_mut());
    let (expected_cleanup, expected_batch, expected_ledger) =
        target_permanent_installed_prepared_projection(&app, router);
    app.world_mut()
        .insert_resource(MissingPickableRepairHookDrift {
            targets: repair_targets,
            protected_root,
            first_insert: None,
            later_insertions: 0,
        });

    settle_cleanup_system(app.world_mut());
    {
        let world = app.world();
        let entry = world
            .resource::<RouterNavigation>()
            .entries
            .iter()
            .find(|entry| entry.handle == router)
            .expect("activation retains the exact RouterEntry");
        let Some(PendingTargetPreparationPermanentCleanup::Installed(installed)) =
            entry.pending_back_target_permanent_cleanup.as_ref()
        else {
            panic!("activation must retain the whole installed settlement owner")
        };
        let TargetPreparationPermanentLedgerHolder::Active(
            ActiveTargetPreparationPermanentLedger::Current(current),
        ) = &installed.ledger
        else {
            panic!("the first settlement tick must activate the unique Current owner")
        };
        let registry = world.resource::<RouteEntityRegistry>();
        assert!(repair_targets.iter().all(|target| {
            target_authority_missing_pickable_repair_is_exact(
                world,
                registry,
                &current.validation,
                *target,
            )
        }));
        assert!(installed.inert.is_none());
        assert_eq!(current.ledger.receipt_count(), 0);
    }

    settle_cleanup_system(app.world_mut());

    let drift = app.world().resource::<MissingPickableRepairHookDrift>();
    let first_insert = drift
        .first_insert
        .expect("the Current repair must perform its first real Pickable insertion");
    let later_target = repair_targets
        .into_iter()
        .find(|target| *target != first_insert)
        .expect("the fixture retains a later authorized repair target");
    assert_eq!(
        drift.later_insertions, 0,
        "the first hook-triggered partition drift must stop all later component writes"
    );
    assert_eq!(
        app.world().get::<Pickable>(first_insert),
        Some(&Pickable::IGNORE)
    );
    assert!(
        app.world().get::<Pickable>(later_target).is_none(),
        "the later authorized target must remain untouched after first-write refreeze fails"
    );
    assert_eq!(
        app.world()
            .get::<ChildOf>(protected_root)
            .map(ChildOf::parent),
        Some(first_insert),
        "the real deferred hook command must drift the frozen target/protected partition"
    );

    let entry = app
        .world()
        .resource::<RouterNavigation>()
        .entries
        .iter()
        .find(|entry| entry.handle == router)
        .expect("the postwrite refreeze retains the exact RouterEntry");
    let Some(PendingTargetPreparationPermanentCleanup::Installed(installed)) =
        entry.pending_back_target_permanent_cleanup.as_ref()
    else {
        panic!("the failed per-write refreeze must retain the whole installed owner")
    };
    let TargetPreparationPermanentLedgerHolder::Active(
        ActiveTargetPreparationPermanentLedger::Current(current),
    ) = &installed.ledger
    else {
        panic!("partition drift must keep the unique ledger owner inert at Current")
    };
    assert!(matches!(
        installed.inert,
        Some(TargetPreparationPermanentInertEvidence::RepairPostWriteRefreeze(
            ref evidence
        )) if evidence.entity == first_insert && evidence.expected != evidence.observed
    ));
    assert!(
        TargetPermanentDispositionProjection::capture_cleanup(&installed.cleanup)
            == expected_cleanup
    );
    assert!(TargetPermanentBatchProjection::capture(&installed.batch) == expected_batch);
    assert!(current.ledger.projection() == expected_ledger);
    assert_eq!(current.ledger.receipt_count(), 0);
    assert!(!current.ledger.issued_attempt_present_for_test());
    assert_eq!(entry.engine.history(), &history_before);
    assert_eq!(entry.engine.active(), &active_before);
    assert!(matches!(
        entry
            .engine
            .request(request)
            .map(|record| record.status().clone()),
        Some(RequestStatus::Running(_))
    ));
}

#[test]
fn back_target_missing_pickable_repair_refreezes_component_values_before_later_writes() {
    #[derive(Resource)]
    struct MissingPickableValueDrift {
        targets: [Entity; 2],
        first_insert: Option<Entity>,
        later_insertions: usize,
    }

    let mut app = App::new();
    app.world_mut()
        .register_component_hooks::<Pickable>()
        .on_insert(|mut world, HookContext { entity, .. }| {
            let Some(mut drift) = world.get_resource_mut::<MissingPickableValueDrift>() else {
                return;
            };
            if !drift.targets.contains(&entity) {
                return;
            }
            if let Some(first) = drift.first_insert {
                if first != entity {
                    drift.later_insertions += 1;
                }
                return;
            }
            drift.first_insert = Some(entity);
            drop(drift);
            world.commands().entity(entity).insert(Pickable {
                should_block_lower: true,
                is_hoverable: true,
            });
        });
    app.add_plugins(BevyUiRouterPlugin::default());
    let (router, _) = install_classifier_permanent_fixture(
        &mut app,
        "back-target-missing-pickable-value-refreeze",
    );
    let _request = stage_real_back_target_applied_commit(&mut app, router);
    let repair_targets = {
        let entry = app
            .world()
            .resource::<RouterNavigation>()
            .entries
            .iter()
            .find(|entry| entry.handle == router)
            .expect("the real Back target retains its exact RouterEntry");
        let current = entry
            .active
            .as_ref()
            .and_then(RealizedBranch::first_frame)
            .and_then(|frame| frame.interactive_entities().first().copied())
            .expect("the current branch retains one Pickable target");
        let Some(PendingBackTargetExecution::ResumeBlocked(
            PendingBackTargetResumeBlocked::AppliedCommitPending(applied),
        )) = entry.pending_back_target_execution.as_ref()
        else {
            panic!("the real Back target must wait at its applied Commit owner")
        };
        let entering = applied
            .pending
            .branch
            .last_frame()
            .and_then(|frame| frame.interactive_entities().first().copied())
            .expect("the entering branch retains a second Pickable target");
        [current, entering]
    };
    for target in repair_targets {
        app.world_mut().entity_mut(target).remove::<Pickable>();
    }
    app.world_mut().flush();

    commit_presentation_system(app.world_mut());
    app.world_mut().insert_resource(MissingPickableValueDrift {
        targets: repair_targets,
        first_insert: None,
        later_insertions: 0,
    });
    settle_cleanup_system(app.world_mut());
    settle_cleanup_system(app.world_mut());

    let drift = app.world().resource::<MissingPickableValueDrift>();
    let first = drift
        .first_insert
        .expect("the Current repair must perform one real Pickable insertion");
    let later = repair_targets
        .into_iter()
        .find(|target| *target != first)
        .expect("the fixture retains a later repair target");
    assert_eq!(
        drift.later_insertions, 0,
        "RED: the first hook value drift must stop every later component write"
    );
    assert_eq!(
        app.world().get::<Pickable>(first),
        Some(&Pickable {
            should_block_lower: true,
            is_hoverable: true,
        }),
        "the Router must not overwrite the observed hook drift after refreeze rejects it"
    );
    assert!(
        app.world().get::<Pickable>(later).is_none(),
        "the later repair target must remain untouched"
    );
    let entry = app
        .world()
        .resource::<RouterNavigation>()
        .entries
        .iter()
        .find(|entry| entry.handle == router)
        .expect("the inert Current owner retains its RouterEntry");
    let Some(PendingTargetPreparationPermanentCleanup::Installed(installed)) =
        entry.pending_back_target_permanent_cleanup.as_ref()
    else {
        panic!("value drift must retain the whole installed owner")
    };
    assert!(matches!(
        installed.ledger,
        TargetPreparationPermanentLedgerHolder::Active(
            ActiveTargetPreparationPermanentLedger::Current(_)
        )
    ));
    assert!(matches!(
        installed.inert,
        Some(TargetPreparationPermanentInertEvidence::RepairPostWriteRefreeze(
            ref evidence
        )) if evidence.entity == first && evidence.expected != evidence.observed
    ));
}

#[test]
fn back_target_missing_pickable_repair_refreezes_registry_manifest_before_later_writes() {
    #[derive(Resource)]
    struct MissingPickableRegistryManifestDrift {
        targets: [(Entity, ExactRegistryClaim); 2],
        first_insert: Option<Entity>,
        later_insertions: usize,
        manifest_drifted: bool,
    }

    let mut app = App::new();
    app.world_mut()
        .register_component_hooks::<Pickable>()
        .on_insert(|mut world, HookContext { entity, .. }| {
            let Some(mut drift) = world.get_resource_mut::<MissingPickableRegistryManifestDrift>()
            else {
                return;
            };
            let Some((_, claim)) = drift.targets.iter().find(|(target, _)| *target == entity)
            else {
                return;
            };
            let claim = claim.clone();
            if let Some(first) = drift.first_insert {
                if first != entity {
                    drift.later_insertions += 1;
                }
                return;
            }
            drift.first_insert = Some(entity);
            drop(drift);

            let changed = {
                let mut registry = world.resource_mut::<RouteEntityRegistry>();
                let Some(original) = registry
                    .record(entity)
                    .map(|record| record.manifest().clone())
                else {
                    return;
                };
                let drifted =
                    ComponentManifest::new(original.component_ids().iter().copied().skip(1));
                original != drifted
                    && registry.compare_exchange_manifest_exact(&claim, &original, drifted)
            };
            world
                .resource_mut::<MissingPickableRegistryManifestDrift>()
                .manifest_drifted = changed;
        });
    app.add_plugins(BevyUiRouterPlugin::default());
    let (router, _) = install_classifier_permanent_fixture(
        &mut app,
        "back-target-missing-pickable-registry-manifest-refreeze",
    );
    let _request = stage_real_back_target_applied_commit(&mut app, router);
    let repair_targets = {
        let entry = app
            .world()
            .resource::<RouterNavigation>()
            .entries
            .iter()
            .find(|entry| entry.handle == router)
            .expect("the real Back target retains its exact RouterEntry");
        let current = entry
            .active
            .as_ref()
            .and_then(RealizedBranch::first_frame)
            .and_then(|frame| frame.interactive_entities().first().copied())
            .expect("the current branch retains one Pickable target");
        let Some(PendingBackTargetExecution::ResumeBlocked(
            PendingBackTargetResumeBlocked::AppliedCommitPending(applied),
        )) = entry.pending_back_target_execution.as_ref()
        else {
            panic!("the real Back target must wait at its applied Commit owner")
        };
        let entering = applied
            .pending
            .branch
            .last_frame()
            .and_then(|frame| frame.interactive_entities().first().copied())
            .expect("the entering branch retains a second Pickable target");
        [current, entering]
    };
    let repair_claims = repair_targets.map(|target| {
        (
            target,
            app.world()
                .resource::<RouteEntityRegistry>()
                .record(target)
                .expect("each repair target retains its exact registry claim")
                .claim(),
        )
    });
    for target in repair_targets {
        app.world_mut().entity_mut(target).remove::<Pickable>();
    }
    app.world_mut().flush();

    commit_presentation_system(app.world_mut());
    app.world_mut()
        .insert_resource(MissingPickableRegistryManifestDrift {
            targets: repair_claims,
            first_insert: None,
            later_insertions: 0,
            manifest_drifted: false,
        });
    settle_cleanup_system(app.world_mut());
    settle_cleanup_system(app.world_mut());

    let drift = app
        .world()
        .resource::<MissingPickableRegistryManifestDrift>();
    let first = drift
        .first_insert
        .expect("the Current repair must perform one real Pickable insertion");
    let later = repair_targets
        .into_iter()
        .find(|target| *target != first)
        .expect("the fixture retains a later repair target");
    assert!(
        drift.manifest_drifted,
        "the hook must change only the real registry-manifest predicate input"
    );
    assert_eq!(
        drift.later_insertions, 0,
        "RED: registry-manifest drift after the first hook write must stop later writes"
    );
    assert!(app.world().get::<Pickable>(later).is_none());
    let entry = app
        .world()
        .resource::<RouterNavigation>()
        .entries
        .iter()
        .find(|entry| entry.handle == router)
        .expect("the inert Current owner retains its RouterEntry");
    let Some(PendingTargetPreparationPermanentCleanup::Installed(installed)) =
        entry.pending_back_target_permanent_cleanup.as_ref()
    else {
        panic!("registry-manifest drift must retain the whole installed owner")
    };
    assert!(matches!(
        installed.ledger,
        TargetPreparationPermanentLedgerHolder::Active(
            ActiveTargetPreparationPermanentLedger::Current(_)
        )
    ));
    assert!(matches!(
        installed.inert,
        Some(TargetPreparationPermanentInertEvidence::RepairPostWriteRefreeze(
            ref evidence
        )) if evidence.entity == first && evidence.expected != evidence.observed
    ));
}

#[test]
fn host_registration_loss_after_commit_seal_cancels_publication_and_settles_owner() {
    for with_active in [false, true] {
        let mut app = App::new();
        app.add_plugins(BevyUiRouterPlugin::default());
        let observed = std::sync::Arc::new(std::sync::Mutex::new(Vec::new()));
        let router = install_nested_router(&mut app, observed, true);
        app.update();
        if with_active {
            commit_initial_nested_branch(&mut app, router);
        }
        let (host, top_slot, history_before, active_before) = {
            let entry = &app.world().resource::<RouterNavigation>().entries[0];
            let binding = entry.host.as_ref().unwrap();
            (
                binding.host,
                binding.top_slot,
                entry.engine.history().clone(),
                entry.engine.active().clone(),
            )
        };
        let request =
            prepare_nested_branch_for_commit(&mut app, router, RouteLocation::new("/items/2"));
        assert!(app.world().get::<RouterHostRegistration>(host).is_some());
        assert!(
            app.world_mut()
                .resource_mut::<RouterNavigation>()
                .testing_remove_host_registration_after_next_commit_seal(router)
        );

        // Change the real registration only after Core has sealed this commit;
        // the production authority predicate must reject before publication.
        commit_presentation_system(app.world_mut());

        {
            let navigation = app.world().resource::<RouterNavigation>();
            assert!(navigation.testing_commit_sealed_registration_removal_fired(router));
            assert!(app.world().get::<RouterHostRegistration>(host).is_none());
            let entry = &navigation.entries[0];
            assert_eq!(entry.engine.history(), &history_before);
            assert_eq!(entry.engine.active(), &active_before);
            // Cancellation consumes publication authority, while ECS retains
            // the physical pending owner for the next authority observation.
            let pending = entry.pending_commit.as_ref().unwrap();
            let ticket = pending.ticket.as_ref().unwrap();
            assert_eq!(
                entry.engine.inspect_commit_identity(ticket),
                Err(IntegrationError::Stale),
                "a cancelled CommitSealed ticket cannot authorize another commit"
            );
            assert!(pending.final_task.is_none());
            assert!(pending.branch.as_realized().claims().all(|claim| {
                claim.lifecycle() == EntityLifecycle::PreparedInert
                    && !app
                        .world()
                        .resource::<RouterInputGate>()
                        .allows_pointer(claim.entity())
            }));
            assert!(entry.cleanup_ledger.is_none());
            assert!(entry.post_commit_compound.is_none());
            assert!(entry.authority_protocol_residual.is_none());
            assert!(
                entry
                    .engine
                    .request(request)
                    .unwrap()
                    .trace()
                    .iter()
                    .all(|event| { event.kind() != NavigationTraceEventKind::CommitPublished })
            );
        }

        for _ in 0..16 {
            app.update();
            let entry = &app.world().resource::<RouterNavigation>().entries[0];
            assert_eq!(entry.engine.history(), &history_before);
            if matches!(
                entry.engine.request(request).unwrap().status(),
                RequestStatus::Failed(_)
            ) {
                break;
            }
        }
        let entry = &app.world().resource::<RouterNavigation>().entries[0];
        let record = entry.engine.request(request).unwrap();
        assert!(matches!(record.status(), RequestStatus::Failed(failure)
            if failure.kind() == NavigationFailureKind::HostLost));
        assert!(
            record
                .trace()
                .iter()
                .all(|event| { event.kind() != NavigationTraceEventKind::CommitPublished })
        );
        assert_eq!(entry.engine.history(), &history_before);
        assert_eq!(entry.engine.active().kind(), ActivePresentationKind::None);
        assert_eq!(
            entry.engine.snapshot().availability(),
            &RouterAvailability::Unavailable(RouterUnavailableReason::HostLost)
        );
        assert!(entry.active.is_none());
        assert!(entry.host.is_none());
        assert!(entry.pending_commit.is_none());
        assert!(entry.pending_failed_branch.is_none());
        assert!(entry.cleanup_ledger.is_none());
        assert!(entry.post_commit_compound.is_none());
        assert!(entry.authority_protocol_residual.is_none());
        assert!(!entry.cleanup_summary().foreground_pending());
        assert!(app.world().get_entity(host).is_ok());
        assert!(app.world().get::<RouterHostRegistration>(host).is_none());
        assert!(app.world().get_entity(top_slot).is_err());
    }
}

#[test]
fn precommit_host_binding_loss_enters_authority_settlement() {
    let mut app = App::new();
    app.add_plugins(BevyUiRouterPlugin::default());
    install_provisional_detach_reentry(&mut app);
    let (router, _) =
        install_classifier_permanent_fixture(&mut app, "back-precommit-host-binding-loss");
    let request = stage_real_back_target_applied_commit(&mut app, router);
    let (host, history_before, active_before, registration_before) = {
        let world = app.world();
        let entry = world
            .resource::<RouterNavigation>()
            .entries
            .iter()
            .find(|entry| entry.handle == router)
            .expect("the real Back target retains its exact entry");
        let host = entry
            .host
            .as_ref()
            .expect("the applied Back target retains its live HostBinding");
        assert!(validated_host_candidate_is_current(world, &host.candidate));
        (
            host.host,
            entry.engine.history().clone(),
            entry.engine.active().clone(),
            world
                .get::<RouterHostRegistration>(host.host)
                .expect("the app-owned host retains its admitted registration")
                .testing_identity(),
        )
    };

    app.world_mut()
        .entity_mut(host)
        .remove::<RouterHostRegistration>()
        .insert(RouterHostRegistration::new(router));
    app.world_mut().flush();
    let registration_after = app
        .world()
        .get::<RouterHostRegistration>(host)
        .expect("the app-owned host retains the replacement registration")
        .testing_identity();
    assert_ne!(registration_after, registration_before);
    {
        let world = app.world();
        let entry = world
            .resource::<RouterNavigation>()
            .entries
            .iter()
            .find(|entry| entry.handle == router)
            .expect("host incarnation drift retains the RouterEntry");
        let binding = entry
            .host
            .as_ref()
            .expect("the stale HostBinding remains linearly owned before settlement");
        assert!(!validated_host_candidate_is_current(
            world,
            &binding.candidate
        ));
        assert!(!current_host_binding_is_exact(world, binding));
        assert!(matches!(
            entry.pending_back_target_execution.as_ref(),
            Some(PendingBackTargetExecution::ResumeBlocked(
                PendingBackTargetResumeBlocked::AppliedCommitPending(_)
            ))
        ));
    }

    commit_presentation_system(app.world_mut());

    {
        let entry = app
            .world()
            .resource::<RouterNavigation>()
            .entries
            .iter()
            .find(|entry| entry.handle == router)
            .expect("authority recovery retains the RouterEntry shell");
        assert_eq!(entry.engine.history(), &history_before);
        assert_eq!(entry.engine.active(), &active_before);
        assert_eq!(
            entry.engine.snapshot().availability(),
            &RouterAvailability::RecoveringAuthority,
            "precommit HostBinding loss must not safe-stop in AuthorityLostPhysicalMismatch or dispatch-blocked"
        );
        let settlement_owner_count = usize::from(entry.cleanup_ledger.is_some())
            + usize::from(entry.pending_back_target_permanent_cleanup.is_some())
            + usize::from(entry.pending_back_no_target_authority_cleanup.is_some());
        assert_eq!(
            settlement_owner_count, 1,
            "HostBinding loss must enter exactly one existing authority settlement"
        );
        assert!(entry.pending_back_target_execution.is_none());
        assert!(entry.authority_protocol_residual.is_none());
        assert!(
            entry
                .engine
                .request(request)
                .expect("the Back request remains retained during authority recovery")
                .trace()
                .iter()
                .all(|event| event.kind() != NavigationTraceEventKind::HistoryIntentRejected)
        );
    }

    let mut saw_settlement_receipt = false;
    for _ in 0..64 {
        settle_cleanup_system(app.world_mut());
        let entry = app
            .world()
            .resource::<RouterNavigation>()
            .entries
            .iter()
            .find(|entry| entry.handle == router)
            .expect("authority settlement retains its RouterEntry shell");
        let record = entry
            .engine
            .request(request)
            .expect("the authority settlement request remains retained");
        saw_settlement_receipt |= record
            .trace()
            .iter()
            .any(|event| event.kind() == NavigationTraceEventKind::CleanupSettled);
        assert_eq!(entry.engine.history(), &history_before);
        if matches!(record.status(), RequestStatus::Failed(_)) {
            break;
        }
        assert_eq!(
            entry.engine.active(),
            &active_before,
            "active cannot clear before the authority settlement receipt completes"
        );
    }

    let world = app.world();
    let entry = world
        .resource::<RouterNavigation>()
        .entries
        .iter()
        .find(|entry| entry.handle == router)
        .expect("terminal authority settlement retains the RouterEntry shell");
    let record = entry
        .engine
        .request(request)
        .expect("terminal HostBinding loss remains retained");
    assert!(saw_settlement_receipt);
    assert!(matches!(
        record.status(),
        RequestStatus::Failed(failure)
            if matches!(
                failure.kind(),
                NavigationFailureKind::HostLost | NavigationFailureKind::AuthorityLost
            )
    ));
    assert!(
        record
            .trace()
            .iter()
            .all(|event| event.kind() != NavigationTraceEventKind::HistoryIntentRejected)
    );
    assert_eq!(entry.engine.history(), &history_before);
    assert_eq!(entry.engine.active().kind(), ActivePresentationKind::None);
    assert!(entry.active.is_none());
    assert!(entry.host.is_none());
    assert!(entry.pending_commit.as_ref().is_none_or(|pending| {
        pending.ticket.is_none()
            && pending.final_task.is_none()
            && pending.branch.frames().is_empty()
            && pending.branch.child_slots().is_empty()
    }));
    assert!(entry.pending_back_target_execution.is_none());
    assert!(entry.pending_back_target_permanent_cleanup.is_none());
    assert!(entry.cleanup_ledger.is_none());
    assert!(entry.authority_protocol_residual.is_none());
    assert!(entry.pending_back_no_target_authority_cleanup.is_none());
    assert!(entry.pending_back_resolution_action.is_none());
    assert!(entry.pending_bound_back_resolution.is_none());
    assert!(entry.back_capacity_reservations.is_empty());
    let terminal_owners = entry.engine.testing_back_target_permanent_begin_state();
    assert_eq!(terminal_owners.cleanup_owner_count(), 0);
    assert_eq!(terminal_owners.current_owner_count(), 0);
    assert_eq!(terminal_owners.action_owner_count(), 0);
    assert_eq!(terminal_owners.current_history_slot_count(), 0);
    assert_eq!(terminal_owners.cleanup_history_owner_count(), 0);
    assert_eq!(terminal_owners.cleanup_settlement_owner_count(), 0);
    assert_eq!(terminal_owners.queue_len(), 0);
    assert_eq!(terminal_owners.conflicting_owner_count(), 0);
    assert_eq!(
        entry
            .back_capacity_issuer
            .as_ref()
            .expect("the terminal router retains its Back capacity issuer")
            .semantic_snapshot_for_test()
            .outstanding_count(),
        0
    );
    assert!(world.get_entity(host).is_ok());
    assert_eq!(
        world
            .get::<RouterHostRegistration>(host)
            .expect("authority settlement preserves the app-owned replacement registration")
            .testing_identity(),
        registration_after
    );
    assert!(
        world
            .resource::<RouteEntityRegistry>()
            .record(host)
            .is_none()
    );
    assert!(world.get::<RouteOwnershipSeal>(host).is_none());
}

#[test]
fn back_target_authority_protocol_retry_refreezes_source_before_world_access() {
    let mut app = App::new();
    app.add_plugins(BevyUiRouterPlugin::default());
    let (router, _) =
        install_classifier_permanent_fixture(&mut app, "back-authority-protocol-retry-refreeze");
    let request = stage_real_back_target_applied_commit(&mut app, router);
    let (host, history_before, active_before) = {
        let entry = app
            .world()
            .resource::<RouterNavigation>()
            .entries
            .iter()
            .find(|entry| entry.handle == router)
            .expect("the real Back target retains its exact RouterEntry");
        (
            entry
                .host
                .as_ref()
                .expect("the retry fixture retains its live host")
                .host,
            entry.engine.history().clone(),
            entry.engine.active().clone(),
        )
    };
    app.world_mut()
        .entity_mut(host)
        .remove::<RouterHostRegistration>()
        .insert(RouterHostRegistration::new(router));
    app.world_mut().flush();
    crate::cleanup::fail_next_reservation_for_test();

    commit_presentation_system(app.world_mut());
    {
        let entry = app
            .world()
            .resource::<RouterNavigation>()
            .entries
            .iter()
            .find(|entry| entry.handle == router)
            .expect("retry retains the RouterEntry shell");
        assert!(matches!(
            entry.pending_back_target_execution.as_ref(),
            Some(PendingBackTargetExecution::Classifying(
                PendingBackTargetClassification::AuthorityLostProtocol(_)
            ))
        ));
        assert_eq!(
            entry.engine.snapshot().availability(),
            &RouterAvailability::Ready
        );
        assert!(entry.cleanup_ledger.is_none());
        assert_eq!(entry.engine.history(), &history_before);
        assert_eq!(entry.engine.active(), &active_before);
    }
    let world_before = authority_world_fingerprint(app.world());
    let registry = app
        .world_mut()
        .remove_resource::<RouteEntityRegistry>()
        .expect("the retry fixture can drift the exact required-resource predicate");

    let second = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        commit_presentation_system(app.world_mut());
    }));
    app.world_mut().insert_resource(registry);
    assert!(
        second.is_ok(),
        "a stale HostBinding evidence must be refrozen before any required-resource access"
    );
    assert_eq!(authority_world_fingerprint(app.world()), world_before);
    let entry = app
        .world()
        .resource::<RouterNavigation>()
        .entries
        .iter()
        .find(|entry| entry.handle == router)
        .expect("typed source drift retains the RouterEntry shell");
    let Some(PendingBackTargetExecution::Classifying(
        PendingBackTargetClassification::AuthorityLostProtocolSourceDrift { protocol, observed },
    )) = entry.pending_back_target_execution.as_ref()
    else {
        panic!("the exact retry mismatch must retain a typed whole-owner source drift")
    };
    assert_eq!(
        protocol.source.authority_loss,
        Some(LifecyclePreflightEvidence::new(
            LifecyclePreflightSource::HostBinding,
            LifecyclePreflightExpectation::ExactAuthority,
            LifecyclePreflightObserved::Drifted,
        ))
    );
    assert_eq!(protocol.evidence, protocol.source.authority_loss.unwrap());
    assert_eq!(
        observed.authority_loss,
        Some(LifecyclePreflightEvidence::new(
            LifecyclePreflightSource::RequiredResources(RequiredResourceSet::ROUTE_ENTITY_REGISTRY,),
            LifecyclePreflightExpectation::ResourcePresent,
            LifecyclePreflightObserved::Missing,
        ))
    );
    assert!(&protocol.source != observed);
    assert!(entry.cleanup_ledger.is_none());
    assert!(entry.authority_protocol_residual.is_none());
    assert_eq!(
        entry.engine.snapshot().availability(),
        &RouterAvailability::Ready
    );
    assert_eq!(entry.engine.history(), &history_before);
    assert_eq!(entry.engine.active(), &active_before);
    assert!(matches!(
        entry
            .engine
            .request(request)
            .map(|record| record.status().clone()),
        Some(RequestStatus::Running(_))
    ));
}

#[test]
fn back_target_authority_protocol_retry_refreezes_registry_manifest_source() {
    let mut app = App::new();
    app.add_plugins(BevyUiRouterPlugin::default());
    let (router, _) = install_classifier_permanent_fixture(
        &mut app,
        "back-authority-protocol-registry-manifest-refreeze",
    );
    let request = stage_real_back_target_applied_commit(&mut app, router);
    let (host, target, history_before, active_before) = {
        let entry = app
            .world()
            .resource::<RouterNavigation>()
            .entries
            .iter()
            .find(|entry| entry.handle == router)
            .expect("the real Back target retains its exact RouterEntry");
        (
            entry
                .host
                .as_ref()
                .expect("the retry fixture retains its live host")
                .host,
            entry
                .active
                .as_ref()
                .and_then(RealizedBranch::first_frame)
                .and_then(|frame| frame.interactive_entities().first().copied())
                .expect("the active branch retains one exact registry target"),
            entry.engine.history().clone(),
            entry.engine.active().clone(),
        )
    };
    app.world_mut()
        .entity_mut(host)
        .remove::<RouterHostRegistration>()
        .insert(RouterHostRegistration::new(router));
    app.world_mut().flush();
    crate::cleanup::fail_next_reservation_for_test();
    commit_presentation_system(app.world_mut());
    assert!(matches!(
        app.world()
            .resource::<RouterNavigation>()
            .entries
            .iter()
            .find(|entry| entry.handle == router)
            .and_then(|entry| entry.pending_back_target_execution.as_ref()),
        Some(PendingBackTargetExecution::Classifying(
            PendingBackTargetClassification::AuthorityLostProtocol(_)
        ))
    ));

    let (claim, original_manifest) = {
        let record = app
            .world()
            .resource::<RouteEntityRegistry>()
            .record(target)
            .expect("the retry target retains its exact registry record");
        (record.claim(), record.manifest().clone())
    };
    let drifted_manifest =
        ComponentManifest::new(original_manifest.component_ids().iter().copied().skip(1));
    assert_ne!(drifted_manifest, original_manifest);
    assert!(
        app.world_mut()
            .resource_mut::<RouteEntityRegistry>()
            .compare_exchange_manifest_exact(&claim, &original_manifest, drifted_manifest)
    );
    let world_before = authority_world_fingerprint(app.world());

    commit_presentation_system(app.world_mut());

    assert_eq!(authority_world_fingerprint(app.world()), world_before);
    let entry = app
        .world()
        .resource::<RouterNavigation>()
        .entries
        .iter()
        .find(|entry| entry.handle == router)
        .expect("typed registry source drift retains the RouterEntry shell");
    let Some(PendingBackTargetExecution::Classifying(
        PendingBackTargetClassification::AuthorityLostProtocolSourceDrift { protocol, observed },
    )) = entry.pending_back_target_execution.as_ref()
    else {
        panic!("registry-manifest-only drift must retain the whole protocol owner")
    };
    assert!(&protocol.source != observed);
    assert_eq!(protocol.evidence, protocol.source.authority_loss.unwrap());
    assert_eq!(entry.engine.history(), &history_before);
    assert_eq!(entry.engine.active(), &active_before);
    assert!(entry.cleanup_ledger.is_none());
    assert!(entry.authority_protocol_residual.is_none());
    assert!(matches!(
        entry
            .engine
            .request(request)
            .map(|record| record.status().clone()),
        Some(RequestStatus::Running(_))
    ));
}

#[test]
pub(crate) fn active_cycle_enters_authority_settlement() {
    let mut app = App::new();
    app.add_plugins(BevyUiRouterPlugin::default());
    let (router, _) =
        install_classifier_permanent_fixture(&mut app, "back-active-cycle-precedence");
    let request = stage_real_back_target_applied_commit(&mut app, router);
    let history_before = app
        .world()
        .resource::<RouterNavigation>()
        .entries
        .iter()
        .find(|entry| entry.handle == router)
        .expect("the cycle fixture retains its exact entry")
        .engine
        .history()
        .clone();
    let (cycle_child, cycle_parent, entering) = {
        let entry = app
            .world()
            .resource::<RouterNavigation>()
            .entries
            .iter()
            .find(|entry| entry.handle == router)
            .expect("the cycle fixture retains its exact entry");
        let current = entry
            .active
            .as_ref()
            .and_then(RealizedBranch::first_frame)
            .expect("the Back source retains a real observed current frame");
        let owned = current
            .claims()
            .map(ExactRegistryClaim::entity)
            .collect::<std::collections::HashSet<_>>();
        let (cycle_child, cycle_parent) = current
            .cleanup_members()
            .find_map(|(claim, parent)| owned.contains(&parent).then_some((claim.entity(), parent)))
            .expect("the real current closure has an owned parent/child edge");
        let Some(PendingBackTargetExecution::ResumeBlocked(
            PendingBackTargetResumeBlocked::AppliedCommitPending(applied),
        )) = entry.pending_back_target_execution.as_ref()
        else {
            panic!("the real Back target must wait at its applied Commit owner")
        };
        let entering = applied
            .pending
            .branch
            .last_frame()
            .and_then(|frame| frame.interactive_entities().first().copied())
            .expect("the real entering branch has one independent drift target");
        (cycle_child, cycle_parent, entering)
    };
    app.world_mut()
        .entity_mut(cycle_parent)
        .insert(ChildOf(cycle_child));
    app.world_mut().entity_mut(entering).remove::<Pickable>();
    app.world_mut().flush();
    assert_eq!(
        app.world()
            .get::<ChildOf>(cycle_parent)
            .map(ChildOf::parent),
        Some(cycle_child)
    );
    assert!(app.world().get::<Pickable>(entering).is_none());

    app.world_mut().resource_scope(
        |world, mut navigation: bevy_ecs::change_detection::Mut<RouterNavigation>| {
            let entry = navigation
                .entries
                .iter_mut()
                .find(|entry| entry.handle == router)
                .expect("the production classifier receives the exact Back entry");
            assert!(drive_back_target_applied_commit(world, entry));
        },
    );

    let entry = app
        .world()
        .resource::<RouterNavigation>()
        .entries
        .iter()
        .find(|entry| entry.handle == router)
        .expect("classification retains the exact RouterEntry");
    let Some(PendingBackTargetExecution::Classifying(
        PendingBackTargetClassification::AuthorityLost {
            physical: _,
            settlement: _,
            evidence,
        },
    )) = entry.pending_back_target_execution.as_ref()
    else {
        panic!(
            "current-cycle authority loss must win over entering rejection and install one accepted settlement owner"
        )
    };
    assert_eq!(evidence.source(), LifecyclePreflightSource::LeavingCurrent);
    assert_eq!(evidence.observed(), LifecyclePreflightObserved::Drifted);
    assert!(entry.pending_back_target_permanent_cleanup.is_none());
    assert!(entry.cleanup_ledger.is_none());
    assert!(entry.authority_protocol_residual.is_none());
    assert!(entry.pending_back_no_target_authority_cleanup.is_none());
    assert_eq!(entry.engine.history(), &history_before);
    assert!(matches!(
        entry
            .engine
            .request(request)
            .map(|record| record.status().clone()),
        Some(RequestStatus::Running(_))
    ));
    assert_eq!(
        app.world()
            .get::<ChildOf>(cycle_parent)
            .map(ChildOf::parent),
        Some(cycle_child),
        "classification must not mutate the observed current cycle"
    );
    assert!(app.world().get::<Pickable>(entering).is_none());
}

#[test]
fn back_target_pending_rejection_enters_existing_failed_cleanup() {
    let mut app = App::new();
    install_cleanup_despawn_drift_hook(&mut app);
    app.add_plugins(BevyUiRouterPlugin::default());
    let router = install_atomic_router_at_pattern(
        &mut app,
        "back-target-pending-rejected-failed-cleanup",
        "/:id",
    );
    app.update();
    for location in ["/a", "/b"] {
        let request = app
            .world_mut()
            .resource_mut::<RouterNavigation>()
            .push(router, RouteLocation::new(location))
            .expect("the real A/B history fixture accepts its forward request");
        run_updates_until_succeeded(&mut app, request);
    }

    let request = stage_real_back_target_applied_commit(&mut app, router);
    let (
        entering,
        history_before,
        core_active_before,
        active_frames_before,
        active_claims_before,
        active_facts_before,
        requested_before,
    ) = {
        let entry = app
            .world()
            .resource::<RouterNavigation>()
            .entries
            .iter()
            .find(|entry| entry.handle == router)
            .expect("the real Back target retains its exact RouterEntry");
        let Some(PendingBackTargetExecution::ResumeBlocked(
            PendingBackTargetResumeBlocked::AppliedCommitPending(applied),
        )) = entry.pending_back_target_execution.as_ref()
        else {
            panic!("the real applied Back target must retain its CommitTicket owner")
        };
        let entering = applied
            .pending
            .branch
            .last_frame()
            .and_then(|frame| frame.interactive_entities().first().copied())
            .expect("the real entering A branch has one interactive predicate input");
        let active = entry
            .active
            .as_ref()
            .expect("the published B branch remains the old active presentation");
        let active_claims = active.claims().cloned().collect::<Vec<_>>();
        (
            entering,
            entry.engine.history().clone(),
            entry.engine.active().clone(),
            active
                .frames()
                .iter()
                .map(|frame| frame.frame().clone())
                .collect::<Vec<_>>(),
            active_claims.clone(),
            active_claims
                .iter()
                .map(|claim| {
                    (
                        claim.entity(),
                        nested_protected_fingerprint(app.world(), claim.entity()),
                    )
                })
                .collect::<Vec<_>>(),
            entry
                .engine
                .request(request)
                .expect("the real Back request remains retained")
                .requested()
                .cloned(),
        )
    };
    assert_eq!(requested_before, Some(RouteLocation::new("/a")));

    app.world_mut().entity_mut(entering).remove::<Pickable>();
    app.world_mut().flush();
    assert!(app.world().get::<Pickable>(entering).is_none());

    commit_presentation_system(app.world_mut());

    {
        let entry = app
            .world()
            .resource::<RouterNavigation>()
            .entries
            .iter()
            .find(|entry| entry.handle == router)
            .expect("PendingRejected retains the exact RouterEntry");
        let evidence = match entry.pending_back_target_execution.as_ref() {
            Some(PendingBackTargetExecution::Classifying(
                PendingBackTargetClassification::PendingRejectedUnaccepted { evidence, .. },
            ))
            | Some(PendingBackTargetExecution::Classifying(
                PendingBackTargetClassification::PendingRejected { evidence, .. },
            )) => evidence,
            _ => panic!(
                "the production classifier must preserve entering-only drift as a typed PendingRejected owner"
            ),
        };
        assert_eq!(evidence.source(), LifecyclePreflightSource::PendingEntering);
        assert_eq!(
            evidence.expectation(),
            LifecyclePreflightExpectation::ExactAuthority
        );
        assert_eq!(evidence.observed(), LifecyclePreflightObserved::Drifted);
        assert_eq!(entry.engine.history(), &history_before);
        assert_eq!(entry.engine.active(), &core_active_before);
        assert!(entry.pending_back_target_permanent_cleanup.is_none());
        assert!(entry.authority_protocol_residual.is_none());
        assert!(
            entry
                .engine
                .request(request)
                .expect("the classified Back request remains retained")
                .trace()
                .iter()
                .all(|event| event.kind() != NavigationTraceEventKind::HistoryIntentRejected)
        );
    }

    let mut saw_existing_failed_cleanup = false;
    for _ in 0..4 {
        commit_presentation_system(app.world_mut());
        let entry = app
            .world()
            .resource::<RouterNavigation>()
            .entries
            .iter()
            .find(|entry| entry.handle == router)
            .expect("the pending rejection retains its RouterEntry");
        saw_existing_failed_cleanup = matches!(
            entry
                .pending_failed_branch
                .as_ref()
                .map(|failed| &failed.terminal),
            Some(PendingFailedBranchTerminal::BackTargetPendingRejected { .. })
        );
        if saw_existing_failed_cleanup {
            let expected_evidence = LifecyclePreflightEvidence::new(
                LifecyclePreflightSource::PendingEntering,
                LifecyclePreflightExpectation::ExactAuthority,
                LifecyclePreflightObserved::Drifted,
            );
            assert_eq!(
                pending_failed_branch_preflight_evidence_for_test(
                    entry
                        .pending_failed_branch
                        .as_ref()
                        .expect("the existing cleanup retains its pending owner")
                ),
                Some(expected_evidence),
                "RED: PendingRejected evidence must remain typed on the existing failure-cleanup owner"
            );
            assert_eq!(
                entry.active.as_ref().map(|active| {
                    active
                        .frames()
                        .iter()
                        .map(|frame| frame.frame().clone())
                        .collect::<Vec<_>>()
                }),
                Some(active_frames_before.clone()),
                "rejecting the splice must restore the exact old active branch before cleanup"
            );
            assert_eq!(
                entry
                    .active
                    .as_ref()
                    .expect("failed cleanup retains the old active branch")
                    .claims()
                    .cloned()
                    .collect::<Vec<_>>(),
                active_claims_before
            );
            for (entity, facts_before) in &active_facts_before {
                assert_eq!(
                    nested_protected_fingerprint(app.world(), *entity),
                    *facts_before,
                    "pending-only cleanup must preserve every old-active physical fact"
                );
            }
            break;
        }
    }
    assert!(
        saw_existing_failed_cleanup,
        "RED: accepted PendingRejected must enter the existing pending_failed_branch cleanup chain"
    );

    let (despawn_trigger, despawn_trigger_claim) = {
        let entry = app
            .world()
            .resource::<RouterNavigation>()
            .entries
            .iter()
            .find(|entry| entry.handle == router)
            .expect("the pending failure cleanup retains its RouterEntry");
        let failed = entry
            .pending_failed_branch
            .as_ref()
            .expect("the typed pending-rejected owner remains installed");
        let manifest = FrozenCleanupManifest::from_failed_prepared_branch(
            app.world(),
            app.world().resource::<RouteEntityRegistry>(),
            &failed.branch,
        )
        .expect("the exact entering branch freezes its existing cleanup manifest");
        let despawn_trigger = manifest.entities()[0];
        let claim = app
            .world()
            .resource::<RouteEntityRegistry>()
            .record(despawn_trigger)
            .expect("the first cleanup target retains its exact registry record")
            .claim();
        (despawn_trigger, claim)
    };
    app.world_mut().insert_resource(CleanupDespawnDrift {
        target: despawn_trigger,
        action: CleanupDespawnDriftAction::TargetRegistryClaim(despawn_trigger_claim.clone()),
    });
    settle_cleanup_system(app.world_mut());
    {
        let entry = app
            .world()
            .resource::<RouterNavigation>()
            .entries
            .iter()
            .find(|entry| entry.handle == router)
            .expect("partial settlement retains its RouterEntry");
        let ledger = stopped_cleanup_residual(entry, request);
        assert_eq!(
            ledger.failed_preflight_evidence(),
            Some(LifecyclePreflightEvidence::new(
                LifecyclePreflightSource::PendingEntering,
                LifecyclePreflightExpectation::ExactAuthority,
                LifecyclePreflightObserved::Drifted,
            )),
            "the exact PendingRejected evidence must remain on the active cleanup ledger"
        );
        assert_eq!(
            ledger.receipt_count(),
            0,
            "the rejected post-despawn refreeze must not issue a cleanup receipt"
        );
    }
    assert!(
        app.world().get_entity(despawn_trigger).is_err(),
        "the real on_despawn hook must run after the target becomes physically absent"
    );
    let drifted_claim = app
        .world()
        .resource::<RouteEntityRegistry>()
        .record(despawn_trigger)
        .expect("the rejected receipt retains the drifted registry record")
        .claim();
    assert_eq!(drifted_claim.lifecycle(), EntityLifecycle::Quarantined);
    assert_ne!(
        drifted_claim, despawn_trigger_claim,
        "the hook must change the exact claim predicate before receipt commit"
    );
    app.world_mut().remove_resource::<CleanupDespawnDrift>();
    let restored = app
        .world_mut()
        .resource_mut::<RouteEntityRegistry>()
        .compare_exchange_lifecycle(&drifted_claim, despawn_trigger_claim.lifecycle())
        .expect("the test restores only the real settlement predicate input");
    assert_eq!(restored, despawn_trigger_claim);

    let (
        ledger_projection_after_restore,
        evidence_after_restore,
        status_after_restore,
        trace_after_restore,
        diagnostics_after_restore,
        failed_owner_count_after_restore,
    ) = app.world_mut().resource_scope(
        |world, mut navigation: bevy_ecs::change_detection::Mut<RouterNavigation>| {
            let entry = navigation
                .entries
                .iter_mut()
                .find(|entry| entry.handle == router)
                .expect("the failure cleanup retains its RouterEntry");
            let mut ledger = entry
                .authority_protocol_residual
                .as_mut()
                .unwrap()
                .cleanup_settlement_ledger
                .take()
                .expect("partial settlement retains its unique private ledger owner");
            assert!(
                ledger.attempt(world).is_none(),
                "postwrite target drift remains inert after its predicate is restored"
            );
            assert_eq!(ledger.receipt_count(), 0);
            assert!(!ledger.is_settled());
            assert!(ledger.pending_completion().is_none());
            let evidence = ledger
                .failure_cleanup_refreeze_evidence_for_test()
                .cloned()
                .expect("the postwrite stop retains typed target evidence");
            assert_eq!(
                evidence.stage(),
                crate::cleanup::FailureCleanupTransitionStage::PhysicalAbsent(despawn_trigger)
            );
            let crate::cleanup::FailureCleanupPartitionRefreezeFailure::Target {
                entity,
                observed: Some(observed),
                ..
            } = evidence.failure()
            else {
                panic!("the postwrite stop retains exact observed target evidence")
            };
            assert_eq!(*entity, despawn_trigger);
            assert!(!observed.is_present());
            let observed_claim = observed
                .registry_claim()
                .expect("the absent target retains its drifted registry claim");
            assert_eq!(observed_claim.lifecycle(), EntityLifecycle::Quarantined);
            assert_ne!(observed_claim, &despawn_trigger_claim);
            let failed_owner_count = ledger.failed_prepared_frames().len();
            let request_view = entry
                .engine
                .request(request)
                .expect("the inert cleanup retains its exact Back request");
            let stable = (
                ledger.projection(),
                evidence,
                request_view.status().clone(),
                request_view.trace().to_vec(),
                request_view.diagnostics().to_vec(),
                failed_owner_count,
            );
            entry
                .authority_protocol_residual
                .as_mut()
                .unwrap()
                .cleanup_settlement_ledger = Some(ledger);
            stable
        },
    );
    assert!(
        failed_owner_count_after_restore > 0,
        "the failed branch owner remains linearly held by the inert cleanup"
    );
    assert!(matches!(status_after_restore, RequestStatus::Failed(_)));

    for _ in 0..3 {
        settle_cleanup_system(app.world_mut());
        let entry = app
            .world()
            .resource::<RouterNavigation>()
            .entries
            .iter()
            .find(|entry| entry.handle == router)
            .expect("the inert failure cleanup retains its RouterEntry");
        let ledger = stopped_cleanup_residual(entry, request);
        let request_view = entry
            .engine
            .request(request)
            .expect("later ticks retain the exact Back request");
        assert!(ledger.projection() == ledger_projection_after_restore);
        assert_eq!(ledger.receipt_count(), 0);
        assert!(!ledger.is_settled());
        assert!(!ledger.issued_attempt_present_for_test());
        assert_eq!(
            ledger.failure_cleanup_refreeze_evidence_for_test(),
            Some(&evidence_after_restore)
        );
        assert_eq!(
            ledger.failed_prepared_frames().len(),
            failed_owner_count_after_restore
        );
        assert_eq!(request_view.status(), &status_after_restore);
        assert_eq!(request_view.trace(), trace_after_restore);
        assert_eq!(request_view.diagnostics(), diagnostics_after_restore);
        assert_eq!(entry.engine.history(), &history_before);
        assert_eq!(entry.engine.active().kind(), ActivePresentationKind::None);
        assert_eq!(
            entry
                .authority_protocol_residual
                .as_ref()
                .unwrap()
                .active
                .as_ref()
                .unwrap()
                .claims()
                .cloned()
                .collect::<Vec<_>>(),
            active_claims_before
        );
        assert!(entry.pending_back_target_permanent_cleanup.is_none());
    }
}

#[test]
fn stale_back_report_receipt_and_publication_are_zero_write() {
    let mut app = App::new();
    app.add_plugins(BevyUiRouterPlugin::default());
    let (router, _) = install_classifier_permanent_fixture(&mut app, "stale-back-artifact-replay");

    let old_back = app
        .world_mut()
        .resource_mut::<RouterNavigation>()
        .back(router)
        .expect("the two-entry fixture admits its older Back");
    collect_navigation_system(app.world_mut());
    drive_navigation_system(app.world_mut());
    let stale_task = {
        let entry = app
            .world()
            .resource::<RouterNavigation>()
            .entries
            .iter()
            .find(|entry| entry.handle == router)
            .expect("the older Back retains its exact entry");
        entry
            .pending_commit
            .as_ref()
            .and_then(|pending| pending.final_task.as_ref())
            .expect("the older Back retains its real report task")
            .testing_duplicate()
    };
    app.world_mut().resource_scope(
        |_world, mut navigation: bevy_ecs::change_detection::Mut<RouterNavigation>| {
            let entry = navigation
                .entries
                .iter_mut()
                .find(|entry| entry.handle == router)
                .expect("the older Back report returns to its exact entry");
            let mut pending = entry
                .pending_commit
                .take()
                .expect("the older Back retains its real pending branch");
            let task = pending
                .final_task
                .take()
                .expect("the older Back retains its real final report task");
            assert!(matches!(
                route_back_target_applied_report(
                    entry,
                    pending,
                    task,
                    BackTargetAppliedReport::LegacyLeaf,
                ),
                RouteBackTargetAppliedOutcome::Handled
            ));
        },
    );
    let stale_publication_ticket = {
        let entry = app
            .world()
            .resource::<RouterNavigation>()
            .entries
            .iter()
            .find(|entry| entry.handle == router)
            .expect("the older Back retains its exact entry");
        let Some(PendingBackTargetExecution::ResumeBlocked(
            PendingBackTargetResumeBlocked::AppliedCommitPending(applied),
        )) = entry.pending_back_target_execution.as_ref()
        else {
            panic!("the older Back must produce one real Commit ticket")
        };
        applied.ticket.testing_duplicate()
    };

    commit_presentation_system(app.world_mut());
    let stale_cleanup = app
        .world()
        .resource::<RouterNavigation>()
        .entries
        .iter()
        .find(|entry| entry.handle == router)
        .and_then(|entry| entry.cleanup_ledger.as_ref())
        .and_then(CleanupLedger::batch)
        .cloned()
        .expect("the published older Back exposes its real cleanup batch token");
    for _ in 0..16 {
        settle_cleanup_system(app.world_mut());
        if matches!(
            app.world()
                .resource::<RouterNavigation>()
                .entries
                .iter()
                .find(|entry| entry.handle == router)
                .and_then(|entry| entry.engine.request(old_back))
                .map(|record| record.status().clone()),
            Some(RequestStatus::Succeeded)
        ) {
            break;
        }
    }
    assert!(matches!(
        app.world()
            .resource::<RouterNavigation>()
            .entries
            .iter()
            .find(|entry| entry.handle == router)
            .and_then(|entry| entry.engine.request(old_back))
            .map(|record| record.status().clone()),
        Some(RequestStatus::Succeeded)
    ));

    let forward = app
        .world_mut()
        .resource_mut::<RouterNavigation>()
        .push(router, RouteLocation::new("/c"))
        .expect("the newer lineage publishes one fresh forward entry");
    run_updates_until_succeeded(&mut app, forward);
    let current_back = app
        .world_mut()
        .resource_mut::<RouterNavigation>()
        .back(router)
        .expect("the newer history admits its own Back lineage");
    collect_navigation_system(app.world_mut());
    drive_navigation_system(app.world_mut());
    publish_snapshots_system(app.world_mut());
    let capture_inputs = |entry: &RouterEntry| {
        entry
            .engine
            .active()
            .frames()
            .iter()
            .map(|frame| {
                let input = entry
                    .engine
                    .current_input(frame)
                    .expect("active frame has published input");
                (
                    frame.clone(),
                    input.location().clone(),
                    input.route(),
                    input.params().clone(),
                    input.origin().clone(),
                    input.failure().cloned(),
                )
            })
            .collect::<Vec<_>>()
    };
    let inputs_before = capture_inputs(
        app.world()
            .resource::<RouterNavigation>()
            .entries
            .iter()
            .find(|entry| entry.handle == router)
            .unwrap(),
    );

    let (
        engine_before,
        history_before,
        current_request_before,
        owner_before,
        requests_before,
        issuer_before,
        world_before,
        registry_before,
        seal_before,
        public_router_before,
        public_old_before,
        public_current_before,
    ) = {
        let world = app.world();
        let entry = world
            .resource::<RouterNavigation>()
            .entries
            .iter()
            .find(|entry| entry.handle == router)
            .expect("the newer Back retains its exact entry");
        let current = entry
            .engine
            .request(current_back)
            .expect("the newer Back request remains retained");
        let snapshots = world.resource::<RouterSnapshots>();
        let public_old = match snapshots.request(router, old_back) {
            crate::snapshots::RequestLookup::Found(snapshot) => snapshot.clone(),
            _ => panic!("the older Back remains publicly retained"),
        };
        let public_current = match snapshots.request(router, current_back) {
            crate::snapshots::RequestLookup::Found(snapshot) => snapshot.clone(),
            _ => panic!("the newer Back remains publicly retained"),
        };
        (
            entry.engine.snapshot(),
            entry.engine.history().clone(),
            (
                current.requested().cloned(),
                current.status().clone(),
                current.trace().to_vec(),
            ),
            ClassifierPermanentEntryLocalProjection::capture(entry),
            entry.requests.clone(),
            entry
                .back_capacity_issuer
                .as_ref()
                .expect("the newer Back retains its exact capacity issuer")
                .semantic_snapshot_for_test(),
            authority_world_fingerprint(world),
            world.resource::<RouteEntityRegistry>().records().to_vec(),
            world.resource::<RouteEntityRegistry>().latest_issued_seal(),
            snapshots
                .get(router)
                .expect("the newer Back has a public router snapshot")
                .clone(),
            public_old,
            public_current,
        )
    };
    let assert_current_exact = |app: &App| {
        let world = app.world();
        let entry = world
            .resource::<RouterNavigation>()
            .entries
            .iter()
            .find(|entry| entry.handle == router)
            .expect("stale replay retains the newer RouterEntry");
        assert_eq!(
            capture_inputs(entry),
            inputs_before,
            "stale artifacts cannot overwrite published input fields"
        );
        let current = entry
            .engine
            .request(current_back)
            .expect("stale replay retains the newer Back request");
        assert_eq!(entry.engine.snapshot(), engine_before);
        assert_eq!(entry.engine.history(), &history_before);
        assert_eq!(
            (
                current.requested().cloned(),
                current.status().clone(),
                current.trace().to_vec(),
            ),
            current_request_before
        );
        assert!(
            ClassifierPermanentEntryLocalProjection::capture(entry) == owner_before,
            "stale replay must preserve the exact newer ECS owner projection"
        );
        assert_eq!(entry.requests, requests_before);
        assert_eq!(
            entry
                .back_capacity_issuer
                .as_ref()
                .expect("stale replay retains the newer capacity issuer")
                .semantic_snapshot_for_test(),
            issuer_before
        );
        let (driving, task) = match (
            entry.pending_back_target_execution.as_ref(),
            entry
                .pending_commit
                .as_ref()
                .and_then(|pending| pending.final_task.as_ref()),
        ) {
            (Some(PendingBackTargetExecution::Driving(driving)), Some(task)) => (driving, task),
            _ => panic!("stale replay must preserve the newer whole Driving owner"),
        };
        assert!(matches!(
            entry.engine.validate_back_target_execution_pairing(
                BackTargetExecutionOwnerRef::Driving {
                    history: &driving.history,
                    continuation: &driving.continuation,
                },
                BackTargetPhysicalOwnerRef::FrameTask(task),
            ),
            BackTargetExecutionPairingOutcome::Matched
        ));
        assert_eq!(authority_world_fingerprint(world), world_before);
        assert_eq!(
            world.resource::<RouteEntityRegistry>().records(),
            registry_before
        );
        assert_eq!(
            world.resource::<RouteEntityRegistry>().latest_issued_seal(),
            seal_before
        );
        let snapshots = world.resource::<RouterSnapshots>();
        assert_eq!(snapshots.get(router), Some(&public_router_before));
        assert!(matches!(
            snapshots.request(router, old_back),
            crate::snapshots::RequestLookup::Found(snapshot)
                if snapshot == &public_old_before
        ));
        assert!(matches!(
            snapshots.request(router, current_back),
            crate::snapshots::RequestLookup::Found(snapshot)
                if snapshot == &public_current_before
        ));
    };
    assert_current_exact(&app);

    app.world_mut().resource_scope(
            |_world, mut navigation: bevy_ecs::change_detection::Mut<RouterNavigation>| {
                let entry = navigation
                    .entries
                    .iter_mut()
                    .find(|entry| entry.handle == router)
                    .expect("the stale report reaches the newer entry's real consumer");
                let mut pending = entry
                    .pending_commit
                    .take()
                    .expect("the newer Back retains its whole pending commit");
                let current_task = pending
                    .final_task
                    .take()
                    .expect("the newer Back retains its real current final task");
                assert!(entry.engine.is_current_root_back_frame_task(&current_task));

                let RouteBackTargetAppliedOutcome::NonTarget {
                    mut pending,
                    task: returned_stale,
                    report,
                } = route_back_target_applied_report(
                    entry,
                    pending,
                    stale_task,
                    BackTargetAppliedReport::LegacyLeaf,
                )
                else {
                    panic!(
                        "the ECS current-task predicate must reject and return the whole stale applied input"
                    )
                };
                assert!(!entry
                    .engine
                    .is_current_root_back_frame_task(&returned_stale));
                assert!(pending.final_task.is_none());
                pending.final_task = Some(current_task);
                entry.pending_commit = Some(pending);
                drop(returned_stale);
                drop(report);
            },
        );
    publish_snapshots_system(app.world_mut());
    assert_current_exact(&app);

    {
        let mut navigation = app.world_mut().resource_mut::<RouterNavigation>();
        let entry = navigation
            .entries
            .iter_mut()
            .find(|entry| entry.handle == router)
            .expect("the stale receipt reaches the newer entry's real consumer");
        assert_eq!(
            entry.engine.observe_cleanup_receipt(
                &stale_cleanup,
                bevy_ui_router_core::prelude::CleanupDisposition::AlreadyAbsent,
            ),
            Err(IntegrationError::Stale)
        );
    }
    publish_snapshots_system(app.world_mut());
    assert_current_exact(&app);

    {
        let mut navigation = app.world_mut().resource_mut::<RouterNavigation>();
        let entry = navigation
            .entries
            .iter_mut()
            .find(|entry| entry.handle == router)
            .expect("the stale publication reaches the newer entry's real consumer");
        assert!(matches!(
            entry
                .engine
                .prepare_commit(&stale_publication_ticket, CleanupManifest::empty(),),
            Err(IntegrationError::Stale)
        ));
    }
    publish_snapshots_system(app.world_mut());
    assert_current_exact(&app);
}

#[derive(Clone, Debug, Eq, PartialEq)]
struct ReadyPlanPermanentSourceProjection {
    physical: ClassifierPermanentSourceProjection,
    focus_leaving: Vec<Entity>,
    frozen_manifest: FrozenCleanupManifest,
    manifest: CleanupManifestView,
}

impl ReadyPlanPermanentSourceProjection {
    fn capture(owner: &PreparationPermanentOwner<BackTargetReadyAcceptanceOwner>) -> Self {
        Self {
            physical: ClassifierPermanentSourceProjection::capture_parts(
                &owner.owner.physical.classified.splice,
                &owner.owner.physical.classified.history,
                &owner.evidence,
            ),
            focus_leaving: owner.owner.physical.focus_leaving.clone(),
            frozen_manifest: owner.owner.frozen_manifest.clone(),
            manifest: owner.owner.manifest.projection(),
        }
    }
}

fn target_permanent_contract_item_between<'a>(source: &'a str, start: &str, end: &str) -> &'a str {
    let tail = &source[source.find(start).expect("contract item must remain named")..];
    &tail[..tail
        .find(end)
        .expect("contract item boundary must remain named")]
}

fn target_permanent_production_source() -> &'static str {
    include_str!("navigation.rs")
        .split_once(concat!(
            "\n#[cfg(test)]\n",
            "#[path = \"navigation_tests.rs\"]\n",
            "pub(crate) mod tests;"
        ))
        .expect("the production/test boundary must remain named")
        .0
}

struct ProjectedTargetPermanentClaims {
    claims: Vec<ExactRegistryClaim>,
    splice_targets: Vec<Entity>,
    top_slot: Entity,
}

fn projected_target_permanent_claims(
    world: &World,
    splice: &SealedReconciliationSplice,
    top_slot_claim: &ExactRegistryClaim,
) -> ProjectedTargetPermanentClaims {
    fn retain(
        candidates: &mut std::collections::HashMap<
            Entity,
            (ExactRegistryClaim, EntityLifecycle, u8),
        >,
        claim: &ExactRegistryClaim,
        lifecycle: EntityLifecycle,
        priority: u8,
    ) {
        match candidates.entry(claim.entity()) {
            std::collections::hash_map::Entry::Vacant(entry) => {
                entry.insert((claim.clone(), lifecycle, priority));
            }
            std::collections::hash_map::Entry::Occupied(mut entry) => {
                assert_eq!(
                    entry.get().0,
                    *claim,
                    "one current registry Entity must retain one exact source claim"
                );
                if priority > entry.get().2 {
                    entry.insert((claim.clone(), lifecycle, priority));
                }
            }
        }
    }

    let mut candidates = std::collections::HashMap::new();
    for claim in splice.entering().claims() {
        retain(&mut candidates, claim, EntityLifecycle::PreparedInert, 0);
    }
    for role in splice.slot_roles() {
        let current_or_shared = role.current() == EntityLifecycle::Active;
        retain(
            &mut candidates,
            role.claim(),
            if current_or_shared {
                EntityLifecycle::Leaving
            } else {
                EntityLifecycle::PreparedInert
            },
            u8::from(current_or_shared),
        );
    }
    for claim in splice.preserved().claims().chain(splice.leaving().claims()) {
        retain(&mut candidates, claim, EntityLifecycle::Leaving, 2);
    }
    retain(&mut candidates, top_slot_claim, EntityLifecycle::Leaving, 3);

    let mut transitions = candidates
        .into_values()
        .map(|(claim, lifecycle, _)| (claim, lifecycle))
        .collect::<Vec<_>>();
    transitions.sort_by_key(|(claim, _)| claim.entity().to_bits());
    let registry = world.resource::<RouteEntityRegistry>();
    let projected = registry
        .prepare_lifecycle_mutation(&transitions)
        .expect("the canonical failure-isolation transitions must accept exact current claims");
    let mut claims = projected.resulting_claims().to_vec();
    claims.sort_by_key(|claim| claim.entity().to_bits());
    let top_slot = top_slot_claim.entity();
    let splice_targets = claims
        .iter()
        .filter(|claim| claim.entity() != top_slot)
        .map(ExactRegistryClaim::entity)
        .collect();
    ProjectedTargetPermanentClaims {
        claims,
        splice_targets,
        top_slot,
    }
}

struct StagedReadyPlanPermanent {
    request: NavigationRequestId,
    owner: PreparationPermanentOwner<BackTargetReadyAcceptanceOwner>,
    host: Entity,
}

fn stage_real_back_target_ready_plan_permanent(
    app: &mut App,
    router: RouterHandle,
) -> StagedReadyPlanPermanent {
    let request = stage_real_back_target_applied_commit(app, router);
    let host = app
        .world()
        .resource::<RouterNavigation>()
        .entries
        .iter()
        .find(|entry| entry.handle == router)
        .and_then(|entry| entry.host.as_ref())
        .expect("the real Ready-plan fixture retains its exact host binding")
        .host;
    let input_gate = app
        .world_mut()
        .remove_resource::<RouterInputGate>()
        .expect("the real fixture starts with its Router input gate");
    let (pending, owner) = app.world_mut().resource_scope(
        |world, mut navigation: bevy_ecs::change_detection::Mut<RouterNavigation>| {
            let entry = navigation
                .entries
                .iter_mut()
                .find(|entry| entry.handle == router)
                .unwrap();
            assert!(drive_back_target_applied_commit(world, entry));
            let Some(PendingBackTargetExecution::Classifying(
                PendingBackTargetClassification::ReadyAwaitingAcceptance(owner),
            )) = entry.pending_back_target_execution.take()
            else {
                panic!("the real classifier must retain the Ready acceptance owner");
            };
            (entry.pending_commit.take().unwrap(), owner)
        },
    );
    // The production publisher now starts after every preparation scope exits.
    publish_ready_back_target(app.world_mut(), router, pending, owner);
    app.world_mut().insert_resource(input_gate);
    let ready_plan_owner = {
        let mut navigation = app.world_mut().resource_mut::<RouterNavigation>();
        let entry = navigation
            .entries
            .iter_mut()
            .find(|entry| entry.handle == router)
            .unwrap();
        let Some(PendingBackTargetExecution::Classifying(
            PendingBackTargetClassification::ReadyPlanPermanent(owner),
        )) = entry.pending_back_target_execution.take()
        else {
            panic!(
                "the production missing-resource plan predicate must retain the whole Ready-plan permanent source"
            );
        };
        owner
    };
    let evidence = match &ready_plan_owner.evidence {
        PreparationPermanentEvidence::PhysicalPreparationContradiction(evidence) => evidence,
        #[cfg(feature = "bsn")]
        PreparationPermanentEvidence::NativeCleanup(_) => {
            panic!("expected physical preparation contradiction")
        }
    };
    assert_eq!(
        (
            evidence.source(),
            evidence.expectation(),
            evidence.observed(),
        ),
        (
            LifecyclePreflightSource::RequiredResources(RequiredResourceSet::ROUTER_INPUT_GATE,),
            LifecyclePreflightExpectation::ResourcePresent,
            LifecyclePreflightObserved::Missing,
        ),
        "the Ready-plan source must be minted by the real plan-preparation predicate"
    );
    StagedReadyPlanPermanent {
        request,
        owner: ready_plan_owner,
        host,
    }
}

struct StagedTargetPermanentDisposition {
    request: NavigationRequestId,
    host: Entity,
    disposition: TargetPreparationPermanentDisposition,
}

fn stage_real_back_target_permanent_disposition(
    app: &mut App,
    router: RouterHandle,
) -> StagedTargetPermanentDisposition {
    let StagedReadyPlanPermanent {
        request,
        owner,
        host,
    } = stage_real_back_target_ready_plan_permanent(app, router);
    let disposition = app.world_mut().resource_scope(
            |world, mut navigation: bevy_ecs::change_detection::Mut<RouterNavigation>| {
                let entry = navigation
                    .entries
                    .iter_mut()
                    .find(|entry| entry.handle == router)
                    .expect("the real permanent dispatch fixture retains its exact entry");
                match prepare_back_target_ready_plan_permanent(world, entry, owner) {
                    BackTargetReadyPlanPermanentPreparationOutcome::Prepared(disposition) => {
                        disposition
                    }
                    BackTargetReadyPlanPermanentPreparationOutcome::PhysicalMismatch {
                        evidence,
                        ..
                    } => panic!(
                        "the exact real ReadyPlan producer must reach the common disposition; evidence={:?}",
                        (evidence.source(), evidence.expectation(), evidence.observed())
                    ),
                    BackTargetReadyPlanPermanentPreparationOutcome::ReceiverMismatch { .. } => {
                        panic!("the exact real ReadyPlan producer must retain its Core receiver")
                    }
                }
            },
        );
    StagedTargetPermanentDisposition {
        request,
        host,
        disposition,
    }
}

#[derive(Clone, Eq, PartialEq)]
enum TargetPermanentSourceProjection {
    Classifier(ClassifierPermanentSourceProjection),
    ReadyPlan(ReadyPlanPermanentSourceProjection),
}

#[derive(Clone, Eq, PartialEq)]
struct TargetPermanentDispositionProjection {
    source: TargetPermanentSourceProjection,
    lineage_router: RouterHandle,
    lineage_host: Entity,
    lineage_ticket: ViewReportIdentity,
    target_observed: Vec<FrozenTargetPreparationPermanentObservedEntity>,
    protected_roots: Vec<Entity>,
    protected_observed: Vec<FrozenTargetPreparationPermanentObservedEntity>,
    allowed_write: FrozenTargetPreparationPermanentAllowedWriteSet,
    ecs_manifest: FrozenCleanupManifest,
    core_binding: CleanupManifestView,
}

impl std::fmt::Debug for TargetPermanentDispositionProjection {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter
            .debug_struct("TargetPermanentDispositionProjection")
            .field("lineage_router", &self.lineage_router)
            .field("lineage_host", &self.lineage_host)
            .field("lineage_ticket", &"<opaque>")
            .field("target_observed", &self.target_observed)
            .field("protected_roots", &self.protected_roots)
            .field("protected_observed", &self.protected_observed)
            .field("allowed_write", &self.allowed_write)
            .finish_non_exhaustive()
    }
}

impl TargetPermanentDispositionProjection {
    fn capture_cleanup(cleanup: &TargetPreparationPermanentCleanupOwner) -> Self {
        let source = match &cleanup.branch {
            FrozenTargetPreparationPermanentBranch::Classifier { physical, evidence } => {
                TargetPermanentSourceProjection::Classifier(
                    ClassifierPermanentSourceProjection::capture_parts(
                        &physical.splice,
                        &physical.history,
                        evidence,
                    ),
                )
            }
            FrozenTargetPreparationPermanentBranch::ReadyPlan {
                physical,
                normal_frozen_manifest,
                normal_manifest,
                evidence,
            } => TargetPermanentSourceProjection::ReadyPlan(ReadyPlanPermanentSourceProjection {
                physical: ClassifierPermanentSourceProjection::capture_parts(
                    &physical.classified.splice,
                    &physical.classified.history,
                    evidence,
                ),
                focus_leaving: physical.focus_leaving.clone(),
                frozen_manifest: normal_frozen_manifest.clone(),
                manifest: normal_manifest.projection(),
            }),
        };
        Self {
            source,
            lineage_router: cleanup.physical.lineage.router,
            lineage_host: cleanup.physical.lineage.host,
            lineage_ticket: cleanup.physical.lineage.ticket.clone(),
            target_observed: cleanup.physical.target_observed.clone(),
            protected_roots: cleanup.physical.protected.roots.clone(),
            protected_observed: cleanup.physical.protected.observed.clone(),
            allowed_write: cleanup.physical.allowed_write.clone(),
            ecs_manifest: FrozenCleanupManifest::empty(),
            core_binding: CleanupManifest::empty().projection(),
        }
    }

    fn capture(disposition: &TargetPreparationPermanentDisposition) -> Self {
        let mut projection = Self::capture_cleanup(&disposition.cleanup);
        projection.ecs_manifest = disposition.ecs_manifest.clone();
        projection.core_binding = disposition.core_binding.cleanup.projection();
        projection
    }

    fn capture_prepared(disposition: &PreparedTargetPreparationPermanentDisposition) -> Self {
        let mut projection = Self::capture_cleanup(&disposition.cleanup);
        projection.ecs_manifest = disposition.ecs_manifest.clone();
        projection.core_binding = disposition.core_binding.cleanup.projection();
        projection
    }
}

fn assert_prepared_target_permanent_dispatch_owner_is_complete(
    disposition: &PreparedTargetPreparationPermanentDisposition,
) {
    let _settlement = &disposition.settlement;
    let BackTargetPermanentAuthorityManifest {
        cleanup: _core_manifest,
    } = &disposition.core_binding;
    let _prepared_ledger = &disposition.ledger.ledger;
    assert_eq!(
        disposition.ledger.validation.allowed_write, disposition.cleanup.physical.allowed_write,
        "the prepared ledger projection must remain paired with the actual cleanup owner"
    );
}

fn reassemble_prepared_target_permanent_dispatch_owner(
    disposition: PreparedTargetPreparationPermanentDisposition,
) -> PreparedTargetPreparationPermanentDisposition {
    let PreparedTargetPreparationPermanentDisposition {
        cleanup,
        settlement,
        ecs_manifest,
        core_binding,
        ledger,
    } = disposition;
    PreparedTargetPreparationPermanentDisposition {
        cleanup,
        settlement,
        ecs_manifest,
        core_binding,
        ledger,
    }
}

