fn target_permanent_installed_prepared_projection(
    app: &App,
    router: RouterHandle,
) -> (
    TargetPermanentDispositionProjection,
    TargetPermanentBatchProjection,
    PreparedCleanupLedgerProjection,
) {
    let entry = app
        .world()
        .resource::<RouterNavigation>()
        .entries
        .iter()
        .find(|entry| entry.handle == router)
        .expect("the permanent cleanup fixture retains its exact RouterEntry");
    let Some(PendingTargetPreparationPermanentCleanup::Installed(installed)) =
        entry.pending_back_target_permanent_cleanup.as_ref()
    else {
        panic!("the permanent cleanup fixture retains one installed owner")
    };
    let TargetPreparationPermanentLedgerHolder::Prepared(prepared) = &installed.ledger else {
        panic!("the freshly dispatched permanent cleanup starts Prepared")
    };
    (
        TargetPermanentDispositionProjection::capture_cleanup(&installed.cleanup),
        TargetPermanentBatchProjection::capture(&installed.batch),
        prepared.ledger.projection(),
    )
}

fn target_permanent_actual_splice(
    cleanup: &TargetPreparationPermanentCleanupOwner,
) -> &SealedReconciliationSplice {
    match &cleanup.branch {
        FrozenTargetPreparationPermanentBranch::Classifier { physical, .. } => &physical.splice,
        FrozenTargetPreparationPermanentBranch::ReadyPlan { physical, .. } => {
            &physical.classified.splice
        }
    }
}

fn assert_target_permanent_installed_active(
    app: &App,
    router: RouterHandle,
    expected_cleanup: &TargetPermanentDispositionProjection,
    expected_batch: &TargetPermanentBatchProjection,
    expected_ledger: PreparedCleanupLedgerProjection,
    expected_inert: Option<(
        LifecyclePreflightSource,
        LifecyclePreflightExpectation,
        LifecyclePreflightObserved,
    )>,
) {
    let entry = app
        .world()
        .resource::<RouterNavigation>()
        .entries
        .iter()
        .find(|entry| entry.handle == router)
        .expect("the permanent cleanup fixture retains its exact RouterEntry");
    let Some(PendingTargetPreparationPermanentCleanup::Installed(installed)) =
        entry.pending_back_target_permanent_cleanup.as_ref()
    else {
        panic!("the permanent cleanup driver must restore one installed owner")
    };
    assert!(
        TargetPermanentDispositionProjection::capture_cleanup(&installed.cleanup)
            == *expected_cleanup,
        "activation must preserve the actual cleanup branch owner"
    );
    assert!(
        TargetPermanentBatchProjection::capture(&installed.batch) == *expected_batch,
        "activation must preserve the unique Core batch owner"
    );
    let TargetPreparationPermanentLedgerHolder::Active(
        ActiveTargetPreparationPermanentLedger::Current(active),
    ) = &installed.ledger
    else {
        panic!("the installed Prepared ledger must activate exactly once into Current")
    };
    assert_eq!(
        active.validation.lineage.router,
        expected_cleanup.lineage_router
    );
    assert_eq!(
        active.validation.lineage.host,
        expected_cleanup.lineage_host
    );
    assert!(
        active.validation.lineage.ticket == expected_cleanup.lineage_ticket,
        "activation must preserve the exact cleanup ticket lineage"
    );
    assert_eq!(
        active.validation.target_observed,
        expected_cleanup.target_observed
    );
    assert_eq!(
        active.validation.protected.roots,
        expected_cleanup.protected_roots
    );
    assert_eq!(
        active.validation.protected.observed,
        expected_cleanup.protected_observed
    );
    assert_eq!(
        active.validation.allowed_write.splice_targets,
        expected_cleanup.allowed_write.splice_targets
    );
    assert!(
        active.ledger.projection() == expected_ledger,
        "activation must preserve ledger domain, manifest, obligation and receipt identity"
    );
    assert_eq!(
        active.ledger.receipt_count(),
        0,
        "activation-only cleanup must not observe or settle receipts"
    );
    match (&installed.inert, expected_inert) {
        (None, None) => {}
        (Some(TargetPreparationPermanentInertEvidence::Physical(evidence)), Some(expected)) => {
            assert_eq!(
                (
                    evidence.source(),
                    evidence.expectation(),
                    evidence.observed()
                ),
                expected,
                "activation drift must retain its exact typed physical evidence"
            )
        }
        _ => panic!("activation must retain the expected exact inert disposition"),
    }
}

fn assert_target_permanent_activation_tick(
    app: &mut App,
    router: RouterHandle,
    request: NavigationRequestId,
    host: Entity,
    expected_cleanup: &TargetPermanentDispositionProjection,
    expected_batch: &TargetPermanentBatchProjection,
    expected_ledger: PreparedCleanupLedgerProjection,
    expected_inert: Option<(
        LifecyclePreflightSource,
        LifecyclePreflightExpectation,
        LifecyclePreflightObserved,
    )>,
) {
    let zero_write_before =
        ReadyPlanPermanentZeroWriteProjection::capture(app, router, request, host);
    let engine_before = app
        .world()
        .resource::<RouterNavigation>()
        .entries
        .iter()
        .find(|entry| entry.handle == router)
        .expect("the activation fixture retains its exact entry")
        .engine
        .snapshot();

    settle_cleanup_system(app.world_mut());

    assert_target_permanent_installed_active(
        app,
        router,
        expected_cleanup,
        expected_batch,
        expected_ledger,
        expected_inert,
    );
    let entry = app
        .world()
        .resource::<RouterNavigation>()
        .entries
        .iter()
        .find(|entry| entry.handle == router)
        .expect("activation must retain its exact entry");
    assert_eq!(entry.engine.snapshot(), engine_before);
    assert_eq!(target_permanent_begin_callback_calls(app, router), 1);
    assert_eq!(
        ReadyPlanPermanentZeroWriteProjection::capture(app, router, request, host),
        zero_write_before,
        "one activation tick must preserve Core, public, registry and World state"
    );
}

fn stage_real_back_target_prepared_permanent_disposition(
    app: &mut App,
    router: RouterHandle,
    foreign_router: RouterHandle,
) -> PreparedTargetPreparationPermanentDisposition {
    let staged = stage_real_back_target_permanent_disposition(app, router);
    publish_snapshots_system(app.world_mut());
    swap_ready_plan_test_engines(app, router, foreign_router);
    let prepared = match dispatch_real_back_target_permanent(app, router, staged.disposition) {
        BackTargetPermanentDispatchOutcome::ReceiverMismatch {
            disposition,
            mismatch: _,
        } => disposition,
        _ => panic!(
            "the foreign receiver fixture must whole-return one genuinely reserved prepared disposition"
        ),
    };
    swap_ready_plan_test_engines(app, router, foreign_router);
    prepared
}

#[derive(Clone, Copy)]
enum TargetPermanentInitialMismatchFault {
    MissingHost,
    MissingTicket,
    OccupiedPermanentHolder,
    MissingRegistry,
    TargetManifestDrift,
    ProtectedManifestDrift,
    AllowedWriteTargetMismatch,
    AllowedWriteProtectedOverlap,
}

fn assert_target_permanent_initial_mismatch_evidence(
    label: &'static str,
    fault: TargetPermanentInitialMismatchFault,
    expected: (
        LifecyclePreflightSource,
        LifecyclePreflightExpectation,
        LifecyclePreflightObserved,
    ),
) {
    let mut app = App::new();
    app.add_plugins(BevyUiRouterPlugin::default());
    let (router, _) = install_classifier_permanent_fixture(&mut app, label);
    let mut staged = stage_real_back_target_permanent_disposition(&mut app, router);
    publish_snapshots_system(app.world_mut());

    match fault {
        TargetPermanentInitialMismatchFault::MissingHost => {
            let mut navigation = app.world_mut().resource_mut::<RouterNavigation>();
            let entry = navigation
                .entries
                .iter_mut()
                .find(|entry| entry.handle == router)
                .expect("the missing-host RED retains its exact RouterEntry");
            let _detached_host = entry
                .host
                .take()
                .expect("the exact fixture starts with one app-owned host binding");
        }
        TargetPermanentInitialMismatchFault::MissingTicket => {
            let mut navigation = app.world_mut().resource_mut::<RouterNavigation>();
            let entry = navigation
                .entries
                .iter_mut()
                .find(|entry| entry.handle == router)
                .expect("the missing-ticket RED retains its exact RouterEntry");
            let _detached_ticket = entry
                .pending_commit
                .as_mut()
                .and_then(|pending| pending.ticket.take())
                .expect("the exact fixture starts with one entry-bound CommitTicket");
        }
        TargetPermanentInitialMismatchFault::OccupiedPermanentHolder => {
            let mut navigation = app.world_mut().resource_mut::<RouterNavigation>();
            let entry = navigation
                .entries
                .iter_mut()
                .find(|entry| entry.handle == router)
                .expect("the occupied-holder RED retains its exact RouterEntry");
            assert!(entry.pending_back_target_permanent_cleanup.is_none());
            entry.pending_back_target_permanent_cleanup =
                Some(PendingTargetPreparationPermanentCleanup::TestOccupied);
        }
        TargetPermanentInitialMismatchFault::MissingRegistry => {
            let _registry = app
                .world_mut()
                .remove_resource::<RouteEntityRegistry>()
                .expect("the exact fixture starts with its registry resource");
        }
        TargetPermanentInitialMismatchFault::TargetManifestDrift => {
            let target = staged
                .disposition
                .cleanup
                .physical
                .target_observed
                .first()
                .expect("the exact fixture freezes at least one physical target")
                .entity;
            app.world_mut()
                .entity_mut(target)
                .insert(ReadyPlanPermanentForeignMarker);
        }
        TargetPermanentInitialMismatchFault::ProtectedManifestDrift => {
            let protected = staged
                .disposition
                .cleanup
                .physical
                .protected
                .observed
                .first()
                .expect("the exact fixture freezes at least one protected Entity")
                .entity;
            app.world_mut()
                .entity_mut(protected)
                .insert(ReadyPlanPermanentForeignMarker);
        }
        TargetPermanentInitialMismatchFault::AllowedWriteTargetMismatch => {
            let removed = staged
                .disposition
                .cleanup
                .physical
                .allowed_write
                .splice_targets
                .pop();
            assert!(
                removed.is_some(),
                "the exact fixture freezes at least one allowed-write target"
            );
        }
        TargetPermanentInitialMismatchFault::AllowedWriteProtectedOverlap => {
            let protected = staged
                .disposition
                .cleanup
                .physical
                .protected
                .observed
                .first()
                .expect("the exact fixture freezes at least one protected Entity")
                .entity;
            assert!(
                !staged
                    .disposition
                    .cleanup
                    .physical
                    .allowed_write
                    .splice_targets
                    .contains(&protected),
                "the exact fixture starts with disjoint target and protected closures"
            );
            staged
                .disposition
                .cleanup
                .physical
                .allowed_write
                .splice_targets
                .push(protected);
        }
    }

    let owner_before = TargetPermanentDispositionProjection::capture(&staged.disposition);
    let returned = match dispatch_real_back_target_permanent(&mut app, router, staged.disposition) {
        BackTargetPermanentDispatchOutcome::EntryMismatch {
            disposition,
            evidence,
        } => {
            assert_eq!(
                (
                    evidence.source(),
                    evidence.expectation(),
                    evidence.observed()
                ),
                expected,
                "the initial permanent dispatch must preserve the exact mismatch source, expectation and observed fact"
            );
            disposition
        }
        _ => panic!(
            "the initial permanent dispatch contradiction must fail closed with typed boundary evidence"
        ),
    };
    assert_eq!(
        TargetPermanentDispositionProjection::capture(&returned),
        owner_before,
        "typed mismatch evidence must accompany the whole original disposition"
    );
    assert_eq!(
        target_permanent_begin_callback_calls(&app, router),
        0,
        "initial preflight mismatch must reject before Core begin"
    );
}

#[derive(Clone, Debug, Eq, PartialEq)]
struct ClassifierPermanentAuthorityObservedEntity {
    entity: Entity,
    parent: Option<Entity>,
    children: Vec<Entity>,
    registry_claim: Option<ExactRegistryClaim>,
    registry_manifest: Option<ComponentManifest>,
    ownership_seal: Option<RouteOwnershipSeal>,
    manifest: Option<ComponentManifest>,
    frame_lifecycle: Option<FrameLifecycle>,
    provisional_slot_lifecycle: Option<ProvisionalSlotLifecycle>,
    host_registration_router: Option<RouterHandle>,
    visibility: Option<Visibility>,
    pickable: Option<(bool, bool)>,
    input_barrier: Option<RouterInputBarrier>,
}

impl From<&ClassifierPermanentAuthorityObservedEntity>
    for FrozenTargetPreparationPermanentObservedEntity
{
    fn from(observed: &ClassifierPermanentAuthorityObservedEntity) -> Self {
        Self {
            entity: observed.entity,
            parent: observed.parent,
            children: observed.children.clone(),
            registry_claim: observed.registry_claim.clone(),
            registry_manifest: observed.registry_manifest.clone(),
            ownership_seal: observed.ownership_seal,
            manifest: observed.manifest.clone(),
            frame_lifecycle: observed.frame_lifecycle,
            child_slot_lifecycle: None,
            child_slot_authority: None,
            provisional_slot_lifecycle: observed.provisional_slot_lifecycle,
        }
    }
}

#[derive(Clone, Debug, Eq, PartialEq)]
struct ClassifierPermanentAuthorityStateProjection {
    observed: Vec<ClassifierPermanentAuthorityObservedEntity>,
}

impl ClassifierPermanentAuthorityStateProjection {
    fn capture(world: &World, host: Entity) -> Self {
        let mut entities = observed_descendant_closure(world, [host])
            .into_iter()
            .collect::<Vec<_>>();
        entities.sort_by_key(|entity| entity.to_bits());
        Self {
            observed: entities
                .into_iter()
                .map(|entity| ClassifierPermanentAuthorityObservedEntity {
                    entity,
                    parent: world.get::<ChildOf>(entity).map(ChildOf::parent),
                    children: world
                        .get::<Children>(entity)
                        .map(|children| children.iter().copied().collect())
                        .unwrap_or_default(),
                    registry_claim: world
                        .resource::<RouteEntityRegistry>()
                        .record(entity)
                        .map(|record| record.claim()),
                    registry_manifest: world
                        .resource::<RouteEntityRegistry>()
                        .record(entity)
                        .map(|record| record.manifest().clone()),
                    ownership_seal: world.get::<RouteOwnershipSeal>(entity).copied(),
                    manifest: ComponentManifest::from_world(world, entity),
                    frame_lifecycle: world.get::<FrameLifecycle>(entity).copied(),
                    provisional_slot_lifecycle: world
                        .get::<ProvisionalSlotLifecycle>(entity)
                        .copied(),
                    host_registration_router: world
                        .get::<RouterHostRegistration>(entity)
                        .map(|registration| registration.router()),
                    visibility: world.get::<Visibility>(entity).copied(),
                    pickable: world
                        .get::<Pickable>(entity)
                        .map(|pickable| (pickable.should_block_lower, pickable.is_hoverable)),
                    input_barrier: world.get::<RouterInputBarrier>(entity).copied(),
                })
                .collect(),
        }
    }

    fn observed_for(
        &self,
        entities: impl IntoIterator<Item = Entity>,
    ) -> Vec<FrozenTargetPreparationPermanentObservedEntity> {
        let expected = entities
            .into_iter()
            .collect::<std::collections::HashSet<_>>();
        let mut observed = self
            .observed
            .iter()
            .filter(|observed| expected.contains(&observed.entity))
            .map(FrozenTargetPreparationPermanentObservedEntity::from)
            .collect::<Vec<_>>();
        observed.sort_by_key(|observed| observed.entity.to_bits());
        assert_eq!(
            observed.len(),
            expected.len(),
            "every expected classifier authority Entity must have been captured before the production call"
        );
        observed
    }

    fn protected_for(
        &self,
        host: Entity,
        targets: impl IntoIterator<Item = Entity>,
    ) -> Vec<FrozenTargetPreparationPermanentObservedEntity> {
        let targets = targets
            .into_iter()
            .collect::<std::collections::HashSet<_>>();
        self.observed_for(
            self.observed
                .iter()
                .map(|observed| observed.entity)
                .filter(|entity| *entity != host && !targets.contains(entity)),
        )
    }
}

#[derive(Clone, Debug, Eq, PartialEq)]
struct ReadyPlanPermanentZeroWriteProjection {
    authority: ClassifierPermanentAuthorityStateProjection,
    world: Vec<(Entity, Vec<bevy_ecs::component::ComponentId>)>,
    registry: Vec<crate::registry::RouteEntityRecord>,
    latest_registry_seal: Option<crate::registry::OwnershipSeal>,
    public_router: crate::snapshots::RouterSnapshot,
    public_request: crate::snapshots::NavigationRequestSnapshot,
}

impl ReadyPlanPermanentZeroWriteProjection {
    fn capture(
        app: &App,
        router: RouterHandle,
        request: NavigationRequestId,
        host: Entity,
    ) -> Self {
        let world = app.world();
        let registry = world.resource::<RouteEntityRegistry>();
        let snapshots = world.resource::<RouterSnapshots>();
        let public_request = match snapshots.request(router, request) {
            crate::snapshots::RequestLookup::Found(snapshot) => snapshot.clone(),
            _ => panic!("the Ready-plan fixture retains its public Back request"),
        };
        Self {
            authority: ClassifierPermanentAuthorityStateProjection::capture(world, host),
            world: authority_world_fingerprint(world),
            registry: registry.records().to_vec(),
            latest_registry_seal: registry.latest_issued_seal(),
            public_router: snapshots
                .get(router)
                .expect("the Ready-plan fixture retains its public router snapshot")
                .clone(),
            public_request,
        }
    }
}

