#[test]
fn failure_cleanup_completion_receiver_mismatch_fails_closed_with_paired_owners() {
    let mut app = App::new();
    let (request, _router) = prepare_exact_child_stale_failure(&mut app);
    app.world_mut().resource_mut::<RouterNavigation>().entries[0]
        .failure_cleanup_completion_receiver_drift_armed = true;

    for _ in 0..16 {
        settle_cleanup_system(app.world_mut());
        if app.world().resource::<RouterNavigation>().entries[0]
            .authority_protocol_residual
            .is_some()
        {
            break;
        }
    }

    let entry = &app.world().resource::<RouterNavigation>().entries[0];
    let residual = entry
        .authority_protocol_residual
        .as_ref()
        .expect("a permanent completion receiver mismatch must fail closed once");
    assert!(matches!(
        residual.kind,
        AuthorityProtocolResidualKind::FailureCleanupCompletion(_)
    ));
    assert!(residual.failure_cleanup_completion.is_some());
    assert!(
        residual
            .failure_cleanup_ledger
            .as_ref()
            .is_some_and(|ledger| ledger.failed_prepared_branch().is_some())
    );
    assert!(entry.failure_cleanup_completion.is_none());
    assert!(entry.cleanup_ledger.is_none());
    assert!(matches!(
        entry.engine.request(request).unwrap().status(),
        RequestStatus::Failed(failure)
            if failure.kind() == NavigationFailureKind::AuthorityLost
    ));
    let settled_trace_len = entry.engine.request(request).unwrap().trace().len();

    for _ in 0..3 {
        settle_cleanup_system(app.world_mut());
    }
    let entry = &app.world().resource::<RouterNavigation>().entries[0];
    assert_eq!(
        entry.engine.request(request).unwrap().trace().len(),
        settled_trace_len
    );
    assert!(entry.authority_protocol_residual.is_some());
}

#[test]
fn failure_cleanup_zero_bind_mismatch_retains_exact_evidence_and_redrives_zero() {
    let mut app = App::new();
    app.add_plugins(BevyUiRouterPlugin::default());
    let route_driver = ViewDriverKey::new("permanent-zero-route-driver").unwrap();
    let fallback_driver = ViewDriverKey::new("permanent-zero-fallback-driver").unwrap();
    app.register_ui_view_driver(FailOnceDriver {
        key: route_driver.clone(),
        failed: false,
    })
    .unwrap();
    app.register_ui_view_driver(FailOnceDriver {
        key: fallback_driver.clone(),
        failed: false,
    })
    .unwrap();
    let route_view = RouteViewKey::new("permanent-zero-route-view").unwrap();
    let fallback_view = RouteViewKey::new("permanent-zero-fallback-view").unwrap();
    let routes = RouteTree::builder()
        .root_with_options(
            RoutePattern::path("/").unwrap(),
            RouteNodeOptions::new().with_view(route_view.clone()),
        )
        .unwrap()
        .build()
        .unwrap();
    let mut views = RouteViewRegistry::new();
    views
        .insert(route_view, RouteViewDescriptor::new(route_driver.clone()))
        .unwrap();
    views
        .insert(
            fallback_view.clone(),
            RouteViewDescriptor::new(fallback_driver),
        )
        .unwrap();
    let router = app
        .add_ui_router(RouterConfig::new(routes, views, fallback_view))
        .unwrap();
    app.world_mut()
        .spawn((Node::default(), RouterHostRegistration::new(router)));
    observe_authority_system(app.world_mut());
    let request = app
        .world_mut()
        .resource_mut::<RouterNavigation>()
        .push(router, RouteLocation::new("/"))
        .unwrap();
    collect_navigation_system(app.world_mut());

    drive_navigation_system(app.world_mut());
    let submitted_logical_root = {
        let entry = &app.world().resource::<RouterNavigation>().entries[0];
        assert!(entry.pending_failed_branch.is_none());
        assert!(entry.cleanup_ledger.is_none());
        assert_eq!(
            entry.engine.request(request).unwrap().status(),
            &RequestStatus::Running(NavigationPhase::Recovering)
        );
        let request_snapshot = entry.engine.request(request).unwrap();
        request_snapshot
            .trace()
            .iter()
            .rev()
            .find_map(|event| {
                event
                    .frame()
                    .filter(|frame| frame.origin() == &FrameOrigin::RouterFallback)
                    .cloned()
            })
            .expect("the normal zero cleanup must issue its real fallback task")
    };
    app.world_mut()
        .insert_resource(FailureCleanupPermanentZeroBindMismatch {
            request,
            submitted_logical_root,
            observed_manifest_digest_xor: 1,
            permanent_prepare_calls: 0,
            observed_physical_digest_freezes: 0,
            submitted_manifest_digest: None,
            observed_manifest_digest: None,
            physical_witness_address: None,
            authority_publication_calls: 0,
        });

    drive_navigation_system(app.world_mut());
    {
        let fault = app
            .world()
            .resource::<FailureCleanupPermanentZeroBindMismatch>();
        let submitted_manifest_digest = fault.submitted_manifest_digest.unwrap();
        let observed_manifest_digest = fault.observed_manifest_digest.unwrap();
        let entry = &app.world().resource::<RouterNavigation>().entries[0];
        let FailureCleanupPermanentStableInertOwner::ZeroBindMismatch { holder, evidence } = entry
            .failure_cleanup_permanent
            .as_ref()
            .expect("the real fallback recovery failure retains its zero physical owner")
        else {
            panic!("the observed zero digest drift must install exact typed bind evidence")
        };
        assert_eq!(holder.request(), request);
        assert_eq!(evidence.source_request(), request);
        assert_eq!(evidence.expected_request(), request);
        assert_eq!(evidence.observed_request(), request);
        assert!(evidence.source_matches_expected_receiver());
        assert!(evidence.source_matches_observed_receiver());
        assert!(evidence.expected_manifest_digest_matches(submitted_manifest_digest));
        assert!(evidence.observed_manifest_digest_matches(observed_manifest_digest));
        assert_eq!(evidence.expected_obligation_count(), 0);
        assert_eq!(evidence.observed_obligation_count(), 0);
        assert!(entry.pending_failed_branch.is_none());
        assert!(entry.cleanup_ledger.is_none());
    }

    let (stable_calls, stable_trace_len, stable_terminal_count) = {
        let fault = app
            .world()
            .resource::<FailureCleanupPermanentZeroBindMismatch>();
        assert_eq!(fault.permanent_prepare_calls, 1);
        assert_eq!(fault.observed_physical_digest_freezes, 1);
        assert!(fault.submitted_manifest_digest.is_some());
        assert_eq!(
            fault.submitted_manifest_digest,
            fault
                .observed_manifest_digest
                .map(|observed| observed ^ fault.observed_manifest_digest_xor),
            "the observed physical digest drift must be exact and independent of Core's submitted digest"
        );
        let entry = &app.world().resource::<RouterNavigation>().entries[0];
        assert!(
            matches!(
                entry.failure_cleanup_permanent.as_ref(),
                Some(FailureCleanupPermanentStableInertOwner::ZeroBindMismatch { .. })
            ),
            "the zero mismatch must retain the whole physical owner"
        );
        assert!(entry.pending_failed_branch.is_none());
        assert!(entry.cleanup_ledger.is_none());
        assert!(matches!(
            entry.engine.request(request).unwrap().status(),
            RequestStatus::Running(_)
        ));
        let request_snapshot = entry.engine.request(request).unwrap();
        let trace = request_snapshot.trace();
        (
            (
                fault.permanent_prepare_calls,
                fault.observed_physical_digest_freezes,
            ),
            trace.len(),
            trace
                .iter()
                .filter(|event| event.kind() == NavigationTraceEventKind::RequestTerminal)
                .count(),
        )
    };
    assert_eq!(stable_terminal_count, 0);

    for _ in 0..3 {
        settle_cleanup_system(app.world_mut());
    }

    let fault = app
        .world()
        .resource::<FailureCleanupPermanentZeroBindMismatch>();
    assert_eq!(
        (
            fault.permanent_prepare_calls,
            fault.observed_physical_digest_freezes,
        ),
        stable_calls,
        "a stable zero-bind mismatch must not re-enter Permanent or bind on later settle ticks"
    );
    let entry = &app.world().resource::<RouterNavigation>().entries[0];
    assert!(matches!(
        entry.failure_cleanup_permanent.as_ref(),
        Some(FailureCleanupPermanentStableInertOwner::ZeroBindMismatch { .. })
    ));
    assert!(entry.pending_failed_branch.is_none());
    assert!(entry.cleanup_ledger.is_none());
    let request_snapshot = entry.engine.request(request).unwrap();
    let trace = request_snapshot.trace();
    assert_eq!(trace.len(), stable_trace_len);
    assert_eq!(
        trace
            .iter()
            .filter(|event| event.kind() == NavigationTraceEventKind::RequestTerminal)
            .count(),
        stable_terminal_count,
        "zero-bind mismatch must not invoke terminal publication on later ticks"
    );
}

#[test]
fn failure_cleanup_nonzero_permanent_enters_bounded_r1_authority_owner_once() {
    let mut app = App::new();
    let (request, _router) = prepare_exact_child_stale_failure(&mut app);
    let submitted_logical_root = {
        let entry = &app.world().resource::<RouterNavigation>().entries[0];
        let failed = entry
            .pending_failed_branch
            .as_ref()
            .expect("the real stale child failure retains its cleanup owner");
        assert!(
            !failed.branch.frames().is_empty(),
            "the R1 authority regression requires real nonzero physical cleanup"
        );
        match &failed.terminal {
            PendingFailedBranchTerminal::Task { task, .. } => task.frame().clone(),
            _ => panic!("the stale child fixture must retain its exact report task"),
        }
    };
    app.world_mut()
        .insert_resource(FailureCleanupPermanentZeroBindMismatch {
            request,
            submitted_logical_root,
            observed_manifest_digest_xor: 0,
            permanent_prepare_calls: 0,
            observed_physical_digest_freezes: 0,
            submitted_manifest_digest: None,
            observed_manifest_digest: None,
            physical_witness_address: None,
            authority_publication_calls: 0,
        });

    settle_cleanup_system(app.world_mut());

    let stable_trace_len = {
        let fault = app
            .world()
            .resource::<FailureCleanupPermanentZeroBindMismatch>();
        assert_eq!(fault.permanent_prepare_calls, 1);
        assert_eq!(fault.observed_physical_digest_freezes, 1);
        assert_eq!(fault.authority_publication_calls, 1);
        assert_eq!(
            fault.submitted_manifest_digest, fault.observed_manifest_digest,
            "the nonzero regression keeps the independently frozen physical digest exact"
        );
        let entry = &app.world().resource::<RouterNavigation>().entries[0];
        let residual = entry
            .authority_protocol_residual
            .as_ref()
            .expect("nonzero Permanent must enter the bounded R1 authority residual");
        assert!(matches!(
            residual.kind,
            AuthorityProtocolResidualKind::FailureCleanupPermanentAuthority
        ));
        let pair = residual
            .failure_cleanup_permanent_authority
            .as_ref()
            .expect("the accepted residual retains the exact Core/physical pair");
        assert_eq!(pair.core.request(), request);
        assert_eq!(
            pair.physical.physical().witness_address(),
            fault.physical_witness_address.unwrap(),
            "accepted fail-close must retain the original non-Clone physical payload"
        );
        assert!(
            !pair.physical.physical().branch.frames().is_empty(),
            "the authority residual must retain the same nonzero failed branch"
        );
        let ledger = pair.physical.physical().reserved.projection();
        assert_eq!(
            ledger.manifest_digest(),
            fault.submitted_manifest_digest.unwrap()
        );
        assert!(ledger.obligation_count() > 0);
        assert_eq!(ledger.receipt_count(), 0);
        assert!(entry.failure_cleanup_permanent.is_none());
        assert!(entry.pending_failed_branch.is_none());
        assert!(entry.cleanup_ledger.is_none());
        assert!(matches!(
            entry.engine.request(request).unwrap().status(),
            RequestStatus::Failed(failure)
                if failure.kind() == NavigationFailureKind::AuthorityLost
        ));
        entry.engine.request(request).unwrap().trace().len()
    };

    for _ in 0..3 {
        settle_cleanup_system(app.world_mut());
    }

    let fault = app
        .world()
        .resource::<FailureCleanupPermanentZeroBindMismatch>();
    assert_eq!(
        (
            fault.permanent_prepare_calls,
            fault.observed_physical_digest_freezes,
        ),
        (1, 1),
        "the bounded nonzero authority result must not reprepare on later ticks"
    );
    assert_eq!(fault.authority_publication_calls, 1);
    let entry = &app.world().resource::<RouterNavigation>().entries[0];
    let residual = entry
        .authority_protocol_residual
        .as_ref()
        .expect("later ticks retain the accepted R1 authority residual");
    assert!(residual.failure_cleanup_permanent_authority.is_some());
    assert!(entry.failure_cleanup_permanent.is_none());
    assert!(entry.pending_failed_branch.is_none());
    assert!(entry.cleanup_ledger.is_none());
    assert_eq!(
        entry.engine.request(request).unwrap().trace().len(),
        stable_trace_len
    );
}

#[test]
fn failure_cleanup_nonzero_permanent_rejection_restores_exact_pair_stable_inert() {
    let mut app = App::new();
    let (request, _router) = prepare_exact_child_stale_failure(&mut app);
    let (submitted_logical_root, failed_frames, failed_claims, host_before, active_before) = {
        let entry = &app.world().resource::<RouterNavigation>().entries[0];
        let failed = entry
            .pending_failed_branch
            .as_ref()
            .expect("the real stale child failure retains its cleanup owner");
        let task = match &failed.terminal {
            PendingFailedBranchTerminal::Task { task, .. } => task,
            _ => panic!("the stale child fixture must retain its exact report task"),
        };
        let failed_frames = failed
            .branch
            .frames()
            .iter()
            .map(|frame| frame.frame().clone())
            .collect::<Vec<_>>();
        let failed_claims = failed_branch_primary_claims(&failed.branch)
            .into_iter()
            .cloned()
            .collect::<Vec<_>>();
        let host = ProjectionlessHostProjection::from(
            entry
                .host
                .as_ref()
                .expect("the rejection fixture has a live host"),
        );
        let active = entry.active.as_ref().map(|active| {
            (
                active
                    .frames()
                    .iter()
                    .map(|frame| frame.frame().clone())
                    .collect::<Vec<_>>(),
                active.claims().cloned().collect::<Vec<_>>(),
            )
        });
        (
            task.frame().clone(),
            failed_frames,
            failed_claims,
            host,
            active,
        )
    };
    app.world_mut()
        .insert_resource(FailureCleanupPermanentZeroBindMismatch {
            request,
            submitted_logical_root,
            observed_manifest_digest_xor: 0,
            permanent_prepare_calls: 0,
            observed_physical_digest_freezes: 0,
            submitted_manifest_digest: None,
            observed_manifest_digest: None,
            physical_witness_address: None,
            authority_publication_calls: 0,
        });
    assert!(
        app.world_mut().resource_mut::<RouterNavigation>().entries[0]
            .engine
            .testing_replace_host_admission_with_non_owning_issuer()
    );

    settle_cleanup_system(app.world_mut());

    let stable_trace_len = {
        let fault = app
            .world()
            .resource::<FailureCleanupPermanentZeroBindMismatch>();
        assert_eq!(fault.permanent_prepare_calls, 1);
        assert_eq!(fault.observed_physical_digest_freezes, 1);
        assert_eq!(fault.authority_publication_calls, 0);
        let witness_address = fault.physical_witness_address.unwrap();
        let manifest_digest = fault.submitted_manifest_digest.unwrap();
        let entry = &app.world().resource::<RouterNavigation>().entries[0];
        let FailureCleanupPermanentStableInertOwner::AuthorityRejected(pair) = entry
            .failure_cleanup_permanent
            .as_ref()
            .expect("rejected fail-close retains the exact R1 pair")
        else {
            panic!("the non-owning issuer must reject the R1 authority publication")
        };
        assert_eq!(pair.core.request(), request);
        let physical = pair.physical.physical();
        assert_eq!(physical.witness_address(), witness_address);
        assert_eq!(
            physical
                .branch
                .frames()
                .iter()
                .map(|frame| frame.frame().clone())
                .collect::<Vec<_>>(),
            failed_frames
        );
        assert_eq!(
            failed_branch_primary_claims(&physical.branch)
                .into_iter()
                .cloned()
                .collect::<Vec<_>>(),
            failed_claims
        );
        let ledger = physical.reserved.projection();
        assert_eq!(ledger.manifest_digest(), manifest_digest);
        assert!(ledger.obligation_count() > 0);
        assert_eq!(ledger.receipt_count(), 0);
        assert_eq!(
            ProjectionlessHostProjection::from(
                entry
                    .host
                    .as_ref()
                    .expect("rejection restores the exact host")
            ),
            host_before
        );
        assert_eq!(
            entry.active.as_ref().map(|active| {
                (
                    active
                        .frames()
                        .iter()
                        .map(|frame| frame.frame().clone())
                        .collect::<Vec<_>>(),
                    active.claims().cloned().collect::<Vec<_>>(),
                )
            }),
            active_before
        );
        assert!(entry.authority_protocol_residual.is_none());
        assert!(entry.pending_failed_branch.is_none());
        assert!(entry.cleanup_ledger.is_none());
        assert!(matches!(
            entry.engine.request(request).unwrap().status(),
            RequestStatus::Running(NavigationPhase::CleanupPending)
        ));
        let request_snapshot = entry.engine.request(request).unwrap();
        assert!(
            request_snapshot
                .trace()
                .iter()
                .all(|event| event.kind() != NavigationTraceEventKind::RequestTerminal)
        );
        request_snapshot.trace().len()
    };

    for _ in 0..3 {
        settle_cleanup_system(app.world_mut());
    }

    let fault = app
        .world()
        .resource::<FailureCleanupPermanentZeroBindMismatch>();
    assert_eq!(
        (
            fault.permanent_prepare_calls,
            fault.observed_physical_digest_freezes,
            fault.authority_publication_calls,
        ),
        (1, 1, 0)
    );
    let entry = &app.world().resource::<RouterNavigation>().entries[0];
    let Some(FailureCleanupPermanentStableInertOwner::AuthorityRejected(pair)) =
        entry.failure_cleanup_permanent.as_ref()
    else {
        panic!("later ticks retain the rejected exact R1 pair")
    };
    assert_eq!(pair.core.request(), request);
    assert_eq!(
        pair.physical.physical().witness_address(),
        fault.physical_witness_address.unwrap()
    );
    assert_eq!(
        entry.engine.request(request).unwrap().trace().len(),
        stable_trace_len
    );
}

